    let activeReviewContext = null;
    let activeDrawerRowContext = null;
    let pendingDangerAction = "";
    let pendingDangerTrigger = null;
    let pendingSlotReactivateFingerprint = "";
    const submissionReviewHandoffStoreKey = "ai666SubmissionReviewHandoffs";

    function readSubmissionReviewHandoffs() {
      let persisted = {};
      let tabState = {};
      try {
        persisted = JSON.parse(sessionStorage.getItem(submissionReviewHandoffStoreKey) || "{}") || {};
      } catch (error) {
        persisted = {};
      }
      try {
        tabState = JSON.parse(window.name || "{}")?.[submissionReviewHandoffStoreKey] || {};
      } catch (error) {
        tabState = {};
      }
      return { ...tabState, ...persisted };
    }

    function writeSubmissionReviewHandoff(handoff) {
      if (!handoff?.taskId) return;
      const nextStore = { ...readSubmissionReviewHandoffs(), [handoff.taskId]: handoff };
      try {
        sessionStorage.setItem(submissionReviewHandoffStoreKey, JSON.stringify(nextStore));
      } catch (error) {
        // file:// 原型可能不允许 DOM Storage，继续使用当前标签页状态承接跨页走查。
      }
      let windowState = {};
      try {
        windowState = JSON.parse(window.name || "{}") || {};
      } catch (error) {
        windowState = {};
      }
      window.name = JSON.stringify({ ...windowState, [submissionReviewHandoffStoreKey]: nextStore });
    }

    function getSubmissionReviewHandoff(taskId = "") {
      return taskId ? readSubmissionReviewHandoffs()[taskId] || null : null;
    }

    function submissionReviewHandoffFromDecision(context, state, label, reason, internalNote, logId) {
      if (!context?.taskId || !context.activityId || !context.activityRecordId) return null;
      const sourceStateMap = {
        approved: "内容审核已通过",
        rejected: "内容审核未通过",
        "second-review": "内容复核中",
        returned: "等待用户修改",
      };
      return {
        taskId: context.taskId,
        objectId: context.objectId,
        activityId: context.activityId,
        activityRecordId: context.activityRecordId,
        ruleVersion: context.ruleVersion || "V1",
        decision: state,
        statusLabel: label,
        sourceState: sourceStateMap[state] || label,
        reason,
        internalNote,
        logId,
      };
    }

    function tableRowValue(row, field) {
      const table = row?.closest("table");
      const headers = [...(table?.querySelectorAll("thead [data-review-field]") || [])];
      const index = headers.findIndex((header) => header.dataset.reviewField === field);
      return index >= 0 ? row.children[index]?.textContent?.trim() || "" : "";
    }

    function getReviewContext(trigger) {
      const row = trigger?.closest('tr[data-review-queue]');
      if (!row) return null;
      const status = tableRowValue(row, "status");
      return {
        row,
        queue: row.dataset.reviewQueue || "content",
        taskId: tableRowValue(row, "audit-id"),
        objectType: tableRowValue(row, "object-type"),
        summary: tableRowValue(row, "summary"),
        submitter: tableRowValue(row, "submitter"),
        objectId: row.dataset.reviewObjectId || "[CONTENT_ID]",
        userId: row.dataset.reviewUserId || "",
        sourceType: row.dataset.reviewSourceType || "",
        sourceObjectId: row.dataset.reviewSourceObjectId || "",
        sourcePage: row.dataset.reviewSourcePage || "",
        sourcePageState: row.dataset.reviewSourcePageState || "落点可用",
        sourcePageApproval: row.dataset.reviewSourcePageApproval || "",
        sourcePageLabel: row.dataset.reviewSourcePageLabel || "",
        sourceBendHref: row.dataset.reviewSourceBendHref || "",
        sourceBendState: row.dataset.reviewSourceBendState || (row.dataset.reviewSourceBendHref ? "已登记" : "未登记"),
        publicState: row.dataset.reviewPublicState || "",
        publicStateLabel: row.dataset.reviewPublicStateLabel || "",
        activityId: row.dataset.reviewActivityId || "",
        activityRecordId: row.dataset.reviewActivityRecordId || "",
        ruleVersion: row.dataset.reviewRuleVersion || "",
        status,
        userReason: tableRowValue(row, "user-reason"),
        internalNote: tableRowValue(row, "internal-note"),
        nextStep: row.dataset.reviewNextStep || "确认对象状态后给出处理结论",
        actionable: ["待审核", "审核中", "复核中", "退回修改"].includes(status),
      };
    }

    function syncSubmissionReviewRowsFromHandoffs() {
      const handoffs = readSubmissionReviewHandoffs();
      document.querySelectorAll('tr[data-review-queue="submission"][data-review-activity-id]').forEach((row) => {
        const taskId = tableRowValue(row, "audit-id");
        const handoff = handoffs[taskId];
        if (!handoff) return;
        const reviewHeaders = [...row.closest("table").querySelectorAll("thead [data-review-field]")];
        const fieldIndex = (field) => reviewHeaders.findIndex((header) => header.dataset.reviewField === field);
        const statusClassMap = {
          approved: "tag success",
          rejected: "tag danger",
          "second-review": "tag info",
          returned: "tag warning",
        };
        const secondReviewMap = {
          approved: ["无需复核", "tag gray"],
          rejected: ["可新建复核", "tag gray"],
          "second-review": ["复核中", "tag info"],
          returned: ["等待重提", "tag warning"],
        };
        const statusCell = fieldIndex("status");
        const slaCell = fieldIndex("sla");
        const reasonCell = fieldIndex("user-reason");
        const internalNoteCell = fieldIndex("internal-note");
        const secondReviewCell = fieldIndex("second-review");
        row.dataset.reviewState = handoff.decision;
        row.dataset.reviewSla = handoff.decision === "second-review" ? "normal" : "processed";
        row.dataset.reviewLogId = handoff.logId;
        row.dataset.reviewNextStep = handoff.decision === "approved"
          ? `来源审核已通过；前往 ${handoff.activityId} / ${handoff.activityRecordId} 独立判定活动资格`
          : handoff.decision === "rejected"
            ? "来源审核未通过；不进入活动资格判定，等待用户重新提交"
            : "来源结论尚未完成；活动资格保持等待来源结果";
        if (statusCell >= 0) row.children[statusCell].innerHTML = `<span class="${statusClassMap[handoff.decision] || "tag gray"}">${escapeHtml(handoff.statusLabel)}</span>`;
        if (slaCell >= 0) row.children[slaCell].textContent = handoff.decision === "second-review" ? "正常处理" : "已处理";
        if (reasonCell >= 0) row.children[reasonCell].textContent = handoff.reason || "待填写";
        if (internalNoteCell >= 0 && handoff.internalNote) row.children[internalNoteCell].textContent = handoff.internalNote;
        if (secondReviewCell >= 0) {
          const [reviewLabel, reviewClass] = secondReviewMap[handoff.decision] || ["无需复核", "tag gray"];
          row.children[secondReviewCell].innerHTML = `<span class="${reviewClass}">${reviewLabel}</span>`;
        }
      });
    }

    function reviewRecheckTaskId(sourceTaskId) {
      const sourceSuffix = String(sourceTaskId || "AUD").replace(/^AUD-/, "");
      return `AUD-RV-${sourceSuffix}`;
    }

    function closeReviewRecheckModal() {
      const modal = document.querySelector('[data-modal="review-recheck"]');
      modal?.classList.remove("is-open");
      modal?.setAttribute("aria-hidden", "true");
      document.querySelector(".modal-backdrop[data-close-layer]")?.classList.remove("is-open");
    }

    function openReviewRecheckModal() {
      const context = activeReviewContext;
      if (!context || context.actionable) return;
      const modal = document.querySelector('[data-modal="review-recheck"]');
      if (!modal) return;
      modal.dataset.reviewRecheckSourceTask = context.taskId;
      modal.dataset.reviewRecheckObjectId = context.objectId;
      modal.dataset.reviewRecheckCurrentConclusion = context.status;
      setImmutableIdValue(modal.querySelector('[data-review-recheck-field="source-task"]'), context.taskId, modal);
      setImmutableIdValue(modal.querySelector('[data-review-recheck-field="object-id"]'), context.objectId, modal);
      modal.querySelector('[data-review-recheck-field="current-conclusion"]').value = context.status;
      modal.querySelector('[data-review-recheck-field="reason"]').value = "";
      modal.querySelector('[data-review-recheck-field="assignee"]').value = "复核组";
      modal.querySelector('[data-review-recheck-field="priority"]').value = "normal";
      const error = modal.querySelector("[data-review-recheck-error]");
      if (error) error.hidden = true;
      document.querySelector(".modal-backdrop[data-close-layer]")?.classList.add("is-open");
      modal.classList.add("is-open");
      modal.setAttribute("aria-hidden", "false");
      modal.querySelector('[data-review-recheck-field="reason"]')?.focus();
    }

    function saveReviewRecheckTask() {
      const modal = document.querySelector('[data-modal="review-recheck"]');
      const context = activeReviewContext;
      if (!modal || !context?.row) return;
      const reasonInput = modal.querySelector('[data-review-recheck-field="reason"]');
      const reason = reasonInput?.value?.trim() || "";
      const error = modal.querySelector("[data-review-recheck-error]");
      if (!reason) {
        if (error) error.hidden = false;
        reasonInput?.focus();
        return;
      }
      if (error) error.hidden = true;

      const sourceRow = context.row;
      const tbody = sourceRow.closest("tbody");
      if (!tbody) return;
      const taskId = reviewRecheckTaskId(context.taskId);
      let recheckRow = tbody.querySelector(`[data-review-task-id="${taskId}"]`);
      if (!recheckRow) {
        const assignee = modal.querySelector('[data-review-recheck-field="assignee"]')?.value || "复核组";
        const priority = modal.querySelector('[data-review-recheck-field="priority"]')?.value || "normal";
        const slaState = priority === "urgent" ? "due-soon" : "normal";
        const slaText = priority === "urgent" ? "剩余 30 分钟" : "正常处理";
        const queue = sourceRow.dataset.reviewQueue || "content";
        const objectType = context.objectType || "内容";
        const summary = `${context.summary || "审核对象"} · 复核`;
        const currentResult = context.userReason || `沿用原${context.status || "审核"}结论`;
        sourceRow.insertAdjacentHTML("afterend", `
          <tr data-review-queue="${escapeAttribute(queue)}" data-review-state="second-review" data-review-risk-type="manual" data-review-sla="${escapeAttribute(slaState)}" data-review-assignee="${escapeAttribute(assignee)}" data-review-object-id="${escapeAttribute(context.objectId)}" data-review-user-id="${escapeAttribute(context.userId)}" data-review-source-type="${escapeAttribute(context.sourceType)}" data-review-source-object-id="${escapeAttribute(context.sourceObjectId)}" data-review-source-page="${escapeAttribute(context.sourcePage)}" data-review-source-page-state="${escapeAttribute(context.sourcePageState)}" data-review-source-page-approval="${escapeAttribute(context.sourcePageApproval)}" data-review-source-page-label="${escapeAttribute(context.sourcePageLabel)}" data-review-source-bend-href="${escapeAttribute(context.sourceBendHref)}" data-review-source-bend-state="${escapeAttribute(context.sourceBendState)}" data-review-public-state="${escapeAttribute(context.publicState)}" data-review-public-state-label="${escapeAttribute(context.publicStateLabel)}" data-review-source-task="${escapeAttribute(context.taskId)}" data-review-task-id="${escapeAttribute(taskId)}" data-review-next-step="复核完成前保持原审核结论；完成后按新结论独立处理">
            <td class="mono">${escapeHtml(taskId)}</td><td><span class="tag info">${escapeHtml(objectType)}</span></td><td class="wrap">${escapeHtml(summary)}</td><td>${escapeHtml(context.submitter || "[USER_ID]")}</td><td>原结论复核</td><td>${escapeHtml(reason)}</td><td><span class="tag info">复核中</span></td><td>${escapeHtml(slaText)}</td><td>${escapeHtml(assignee)}</td><td>${escapeHtml(currentResult)}；复核完成前当前结果保持不变</td><td>来源 ${escapeHtml(context.taskId)}；复核原因：${escapeHtml(reason)}</td><td><span class="tag info">新建复核</span></td><td>刚刚</td><td><button class="btn link" data-open-drawer="review-detail">查看详情</button></td>
          </tr>`);
        recheckRow = tbody.querySelector(`[data-review-task-id="${taskId}"]`);
      }

      const feedback = document.querySelector("#globalDrawer [data-review-recheck-feedback]");
      if (feedback) {
        feedback.textContent = `已创建复核任务 ${taskId}；原任务 ${context.taskId} 和“${context.status}”结论保持不变，当前 C端结果继续有效。`;
        feedback.hidden = false;
      }
      const openButton = document.querySelector("#globalDrawer [data-open-review-recheck]");
      if (openButton) {
        openButton.disabled = true;
        openButton.textContent = "复核任务已创建";
      }
      const statusControl = document.querySelector('.view[data-view="review-workbench"] [data-review-filter-control="status"]');
      if (statusControl) statusControl.value = "second-review";
      closeReviewRecheckModal();
      applyReviewFilters();
      if (recheckRow) syncPrototypeAccessibility(recheckRow);
      syncStickyActionColumns();
    }

    function getTableRowContext(trigger) {
      const row = trigger?.closest("tr");
      const table = row?.closest("table");
      if (!row || !table) return null;
      const headers = [...table.querySelectorAll("thead th")].map((header) => header.textContent.trim());
      const values = Object.fromEntries(headers.map((header, index) => [header, row.children[index]?.textContent?.trim() || ""]));
      return { row, table, headers, values };
    }

