    function parseUserPointsBalance(value = "") {
      const normalized = String(value).replace(/,/g, "").trim();
      return /^\d+$/.test(normalized) ? Number(normalized) : null;
    }

    function setUserPointsAdjustmentError(message = "") {
      const error = document.querySelector("[data-user-points-adjustment-error]");
      if (!error) return;
      error.textContent = message;
      error.hidden = !message;
    }

    function syncUserPointsAdjustmentPreview() {
      const modal = document.querySelector('[data-modal="user-points-adjustment"]');
      const current = parseUserPointsBalance(modal?.querySelector('[data-user-points-adjustment-field="current-balance"]')?.value);
      const amountText = modal?.querySelector('[data-user-points-adjustment-field="amount"]')?.value?.trim() || "";
      const direction = modal?.querySelector('[data-user-points-adjustment-field="direction"]')?.value || "credit";
      const nextBalance = modal?.querySelector('[data-user-points-adjustment-field="next-balance"]');
      if (!nextBalance) return null;
      if (current == null || !/^[1-9]\d*$/.test(amountText)) {
        nextBalance.value = "—";
        return null;
      }
      const amount = Number(amountText);
      const next = current + (direction === "credit" ? amount : -amount);
      nextBalance.value = next < 0 ? "限时积分不足" : next.toLocaleString("en-US");
      return next;
    }

    function openUserPointsAdjustment() {
      const view = document.querySelector('.view[data-view="user-detail"]');
      const modal = document.querySelector('[data-modal="user-points-adjustment"]');
      if (!modal) return false;
      const userId = view?.dataset.userContextId || "";
      const profile = userDetailProfiles[userId];
      const balance = parseUserPointsBalance(profile?.points);
      if (!userId || !profile || balance == null) return false;
      modal.dataset.userPointsAdjustmentUserId = userId;
      modal.querySelector("[data-user-points-adjustment-title]").textContent = "调整用户限时积分";
      modal.querySelector("[data-user-points-adjustment-target-label]").textContent = "用户";
      modal.querySelector('[data-user-points-adjustment-field="user"]').value = `${profile.name} · ${userId}`;
      modal.querySelector('[data-user-points-adjustment-field="direction"]').value = "credit";
      modal.querySelector('[data-user-points-adjustment-field="current-balance"]').value = String(balance);
      modal.querySelector('[data-user-points-adjustment-field="amount"]').value = "";
      modal.querySelector('[data-user-points-adjustment-field="next-balance"]').value = "—";
      modal.querySelector('[data-user-points-adjustment-field="reason"]').value = "";
      setUserPointsAdjustmentError();
      document.querySelector(".modal-backdrop[data-close-layer]")?.classList.add("is-open");
      modal.classList.add("is-open");
      modal.setAttribute("aria-hidden", "false");
      modal.querySelector('[data-user-points-adjustment-field="amount"]')?.focus();
      return true;
    }

    function saveUserPointsAdjustment() {
      const modal = document.querySelector('[data-modal="user-points-adjustment"]');
      const userId = modal?.dataset.userPointsAdjustmentUserId || "";
      const profile = userDetailProfiles[userId];
      const balance = parseUserPointsBalance(profile?.points);
      const direction = modal?.querySelector('[data-user-points-adjustment-field="direction"]')?.value || "";
      const amountText = modal?.querySelector('[data-user-points-adjustment-field="amount"]')?.value?.trim() || "";
      const reason = modal?.querySelector('[data-user-points-adjustment-field="reason"]')?.value?.trim() || "";
      if (!modal || !userId || !profile || balance == null) {
        setUserPointsAdjustmentError("当前用户或限时积分余额未登记，不能调整限时积分。");
        return false;
      }
      if (!/^[1-9]\d*$/.test(amountText)) {
        setUserPointsAdjustmentError("限时积分数量必须填写为大于 0 的整数。");
        return false;
      }
      if (!reason) {
        setUserPointsAdjustmentError("请填写本次发放或扣除限时积分的调整原因。");
        return false;
      }
      const amount = Number(amountText);
      if (direction === "debit" && amount > balance) {
        setUserPointsAdjustmentError("扣除限时积分不能超过当前限时积分余额。");
        return false;
      }
      const isCredit = direction === "credit";
      const time = formatActivityLifecycleTime();
      const actionLabel = isCredit ? "发放" : "扣除";
      const sequence = (profile.pointsRows || []).filter((row) => row.manual).length + 1;
      const idSuffix = userId.replace(/^USR-/, "");
      const ledgerId = `PTS-MANUAL-${idSuffix}-${String(sequence).padStart(2, "0")}`;
      const logId = `LOG-${ledgerId}`;
      const nextBalance = balance + (isCredit ? amount : -amount);
      profile.points = nextBalance.toLocaleString("en-US");
      profile.pointsRows = [{
        id: ledgerId,
        source: `后台人工${actionLabel}`,
        change: `${isCredit ? "+" : "-"}${amount}`,
        changeClass: isCredit ? "tag success" : "tag danger",
        result: isCredit ? "已入账" : "已扣减",
        resultClass: "tag success",
        relation: `调整原因：${reason}`,
        time,
        manual: true,
        reason,
        logId,
      }, ...(profile.pointsRows || [])];
      profile.records = `<tr data-user-points-adjustment-record="${escapeAttribute(ledgerId)}" data-user-points-adjustment-reason="${escapeAttribute(reason)}"><td>限时积分调整</td><td><span class="tag success">已记录</span></td><td>${escapeHtml(actionLabel)} ${amount} 限时积分 · ${escapeHtml(reason)} · ${escapeHtml(ledgerId)}</td><td>${escapeHtml(time.slice(0, 10))}</td><td><span class="muted small mono">${escapeHtml(logId)}</span></td></tr>${profile.records || ""}`;
      const listRow = [...document.querySelectorAll('.view[data-view="user-list"] tr[data-user-id]')].find((row) => row.dataset.userId === userId);
      const pointsCell = listRow?.querySelector("[data-user-points-cell]");
      if (pointsCell) pointsCell.textContent = profile.points;
      syncUserDetailContext(userId);
      const view = document.querySelector('.view[data-view="user-detail"]');
      const pointsTab = view?.querySelector('[data-business-tab="points"]');
      if (pointsTab) activateBusinessTab(pointsTab);
      const result = view?.querySelector("[data-user-points-adjustment-result]");
      if (result) {
        result.textContent = `${actionLabel} ${amount} 限时积分已完成，当前限时积分 ${profile.points}；原因已写入 ${logId}，并生成新流水 ${ledgerId}。`;
        result.hidden = false;
      }
      setUserPointsAdjustmentError();
      return true;
    }

    function syncUserDetailContext(userId = "") {
      const resolvedId = userId || new URLSearchParams(window.location.search).get("id") || "USR-1001";
      const profile = userDetailProfiles[resolvedId] || buildContentAuthorDetailProfile(resolvedId) || missingUserDetailProfile;
      const view = document.querySelector('.view[data-view="user-detail"]');
      if (!view) return resolvedId;
      view.dataset.userContextId = resolvedId;
      view.dataset.userContextState = profile.missing ? "missing" : profile.sourceOnly ? "content-author" : "registered";
      const setText = (selector, value) => view.querySelectorAll(selector).forEach((node) => { node.textContent = value; });
      setText("[data-user-detail-id]", resolvedId);
      setText("[data-user-detail-name]", profile.name);
      setText("[data-user-detail-phone]", profile.phone);
      setText("[data-user-detail-points]", profile.points);
      setText("[data-user-detail-invites]", profile.invites);
      setText("[data-user-detail-profile-id]", resolvedId);
      setText("[data-user-detail-profile-name]", profile.name);
      setText("[data-user-detail-profile-phone]", profile.phone);
      setText("[data-user-detail-profile-type]", profile.profileType);
      setText("[data-user-detail-profile-registered]", profile.registeredAt);
      setText("[data-user-detail-profile-login]", profile.lastLogin);
      setText("[data-user-detail-profile-source]", profile.registerSource);
      setText("[data-user-detail-profile-bio]", profile.bio);
      setText("[data-user-detail-content-count]", profile.contentCount);
      setText("[data-user-detail-activity-summary]", profile.activity);
      const avatar = view.querySelector("[data-user-detail-avatar]");
      if (avatar) { avatar.src = profile.avatar; avatar.alt = `${profile.name}头像`; }
      const profileState = view.querySelector("[data-user-detail-profile-state]");
      if (profileState) { profileState.textContent = profile.profileState; profileState.className = profile.profileStateClass; }
      const inviteRows = view.querySelector("[data-user-detail-invite-rows]");
      if (inviteRows) inviteRows.innerHTML = buildUserInviteRows(profile.inviteRows);
      const contentRows = view.querySelector("[data-user-detail-content-rows]");
      if (contentRows) contentRows.innerHTML = buildUserContentRows(profile.contentRows);
      const activityHandoff = view.querySelector("[data-user-detail-activity-handoff]");
      if (activityHandoff) activityHandoff.innerHTML = buildUserSourceHandoff("activity", profile.activityObjects, profile.activityEmpty);
      const pointsRows = view.querySelector("[data-user-detail-points-rows]");
      if (pointsRows) pointsRows.innerHTML = buildUserPointsRows(profile.pointsRows, profile.pointsEmpty);
      const state = view.querySelector("[data-user-detail-state]");
      if (state) { state.textContent = profile.state; state.className = profile.stateClass; }
      const records = view.querySelector("[data-user-detail-profile-records]");
      if (records) records.innerHTML = profile.records;
      const restriction = view.querySelector("[data-user-detail-restriction-summary]");
      if (restriction) restriction.innerHTML = profile.restriction;
      const adjustableBalance = parseUserPointsBalance(profile.points);
      view.querySelectorAll("[data-open-user-points-adjustment]").forEach((button) => {
        const disabled = Boolean(profile.missing) || adjustableBalance == null;
        button.disabled = disabled;
        button.title = disabled ? "用户或限时积分余额未登记，核对后再调整" : "";
        button.dataset.userPointsAdjustmentUserId = resolvedId;
      });
      view.querySelectorAll('[data-danger-action="user-ban"], [data-danger-action="user-unban"]').forEach((button) => {
        button.disabled = Boolean(profile.missing || profile.sourceOnly);
        button.title = profile.missing
          ? "用户 ID 未登记，核对身份后再处理"
          : profile.sourceOnly
            ? "当前仅登记内容作者关系，补齐用户资料后再处理"
            : "";
        const canUnban = ["冻结", "限制登录"].includes(profile.state);
        const isDeleted = profile.state === "删除";
        button.hidden = isDeleted;
        button.dataset.dangerAction = canUnban ? "user-unban" : "user-ban";
        button.dataset.dangerObjectId = resolvedId;
        button.dataset.dangerCurrentState = profile.state;
        button.dataset.dangerResult = canUnban
          ? "账号改为正常；恢复 C端登录和新增操作；历史内容、限时积分、邀请、白名单配置和操作日志保持不变"
          : "账号改为冻结；C端停止登录和新增操作；历史内容、限时积分、邀请、白名单配置和操作日志保留";
        button.className = canUnban ? "btn" : "btn danger";
        button.textContent = canUnban ? "解封账号" : "封禁账号";
      });
      return resolvedId;
    }

    function applyReviewFilters() {
      const view = document.querySelector('.view[data-view="review-workbench"]');
      if (!view) return 0;
      const activeQueue = view.querySelector('[data-review-tab][aria-selected="true"]')?.dataset.reviewTab || "work";
      const sourceId = view.querySelector('[data-review-filter-control="source-id"]')?.value?.trim().toLowerCase() || "";
      const keyword = view.querySelector('[data-review-filter-control="keyword"]')?.value?.trim().toLowerCase() || "";
      const userId = view.querySelector('[data-review-filter-control="user-id"]')?.value?.trim().toLowerCase() || "";
      let visibleCount = 0;
      view.querySelectorAll('[data-table="review-workbench"] tbody tr[data-review-queue]').forEach((row) => {
        const matches =
          row.dataset.reviewQueue === activeQueue &&
          (!sourceId || (row.dataset.reviewObjectId || "").toLowerCase() === sourceId) &&
          (!keyword || (row.dataset.reviewKeyword || "").toLowerCase().includes(keyword)) &&
          (!userId || (row.dataset.reviewUserId || "").toLowerCase() === userId);
        row.hidden = !matches;
        if (matches) visibleCount += 1;
      });
      const empty = view.querySelector("[data-review-empty]");
      if (empty) empty.hidden = visibleCount > 0;
      const count = view.querySelector("[data-review-result-count]");
      if (count) count.textContent = `${visibleCount} 条`;
      return visibleCount;
    }

    function resetReviewFilters() {
      const view = document.querySelector('.view[data-view="review-workbench"]');
      if (!view) return;
      view.querySelectorAll("[data-review-filter-control]").forEach((control) => {
        control.value = "";
      });
      applyReviewFilters();
    }

    function activateReviewTab(queue) {
      const view = document.querySelector('.view[data-view="review-workbench"]');
      if (!view || !queue) return;
      view.querySelectorAll("[data-review-tab]").forEach((tab) => {
        const isActive = tab.dataset.reviewTab === queue;
        tab.classList.toggle("is-active", isActive);
        tab.classList.toggle("ant-segmented-item-selected", isActive);
        tab.setAttribute("aria-selected", isActive ? "true" : "false");
      });
      const sourceLabel = view.querySelector("[data-review-source-id-label]");
      const keywordLabel = view.querySelector("[data-review-keyword-label]");
      const sourceInput = view.querySelector('[data-review-filter-control="source-id"]');
      const keywordInput = view.querySelector('[data-review-filter-control="keyword"]');
      const listTitle = view.querySelector("[data-review-list-title]");
      if (sourceLabel) sourceLabel.textContent = queue === "post" ? "闪念编号" : "作品编号";
      if (keywordLabel) keywordLabel.textContent = queue === "post" ? "正文关键词" : "标题关键词";
      if (sourceInput) sourceInput.placeholder = queue === "post" ? "输入完整闪念编号" : "输入完整作品编号";
      if (keywordInput) keywordInput.placeholder = queue === "post" ? "输入正文关键词" : "输入标题关键词";
      if (listTitle) listTitle.textContent = queue === "post" ? "待审核闪念" : "待审核作品";
      applyReviewFilters();
    }

    let activeReviewAuditRow = null;

    function setReviewAuditDecision(decision = "approve") {
      const modal = document.querySelector('[data-modal="review-audit"]');
      if (!modal) return;
      modal.dataset.reviewAuditDecision = decision;
      modal.querySelectorAll("[data-review-audit-decision]").forEach((button) => {
        const active = button.dataset.reviewAuditDecision === decision;
        button.classList.toggle("is-active", active);
        button.classList.toggle("ant-segmented-item-selected", active);
      });
      const reasonField = modal.querySelector("[data-review-reject-reason-field]");
      if (reasonField) reasonField.hidden = decision !== "reject";
      const submit = modal.querySelector("[data-review-audit-submit]");
      if (submit) submit.textContent = decision === "reject" ? "确认拒绝" : "确认通过";
      const error = modal.querySelector("[data-review-audit-error]");
      if (error) error.hidden = true;
    }

    function openReviewAuditModal(trigger) {
      const row = trigger?.closest('tr[data-review-queue]');
      const modal = document.querySelector('[data-modal="review-audit"]');
      if (!row || !modal) return;
      activeReviewAuditRow = row;
      const object = modal.querySelector("[data-review-audit-object]");
      if (object) object.textContent = `${row.dataset.reviewSourceType || "对象"} · ${row.dataset.reviewObjectId || "—"} · ${row.dataset.reviewKeyword || "—"}`;
      const reason = modal.querySelector("[data-review-audit-reason]");
      if (reason) reason.value = "";
      setReviewAuditDecision("approve");
      document.querySelector(".modal-backdrop[data-close-layer]")?.classList.add("is-open");
      modal.classList.add("is-open");
      modal.setAttribute("aria-hidden", "false");
    }

    function submitReviewAudit() {
      const modal = document.querySelector('[data-modal="review-audit"]');
      if (!modal || !activeReviewAuditRow) return false;
      const decision = modal.dataset.reviewAuditDecision || "approve";
      const reason = modal.querySelector("[data-review-audit-reason]")?.value?.trim() || "";
      const error = modal.querySelector("[data-review-audit-error]");
      if (decision === "reject" && !reason) {
        if (error) {
          error.textContent = "请输入拒绝原因。";
          error.hidden = false;
        }
        return false;
      }
      const objectId = activeReviewAuditRow.dataset.reviewObjectId || "当前对象";
      activeReviewAuditRow.remove();
      const feedback = document.querySelector('.view[data-view="review-workbench"] [data-review-action-feedback]');
      if (feedback) {
        feedback.textContent = `${objectId} 已${decision === "reject" ? "拒绝" : "通过"}${reason ? `：${reason}` : ""}；待审核列表已刷新。`;
        feedback.hidden = false;
      }
      activeReviewAuditRow = null;
      closeLayers();
      applyReviewFilters();
      return true;
    }

    let activeFlashListRow = null;

    function flashListFeedback(message) {
      const view = document.querySelector('.view[data-view="flash-management"]');
      if (!view) return;
      let feedback = view.querySelector("[data-flash-list-feedback]");
      if (!feedback) {
        feedback = document.createElement("div");
        feedback.className = "contract-panel";
        feedback.dataset.flashListFeedback = "";
        feedback.setAttribute("role", "status");
        view.querySelector("[data-flash-filter-panel]")?.insertAdjacentElement("beforebegin", feedback);
      }
      feedback.textContent = message;
      feedback.hidden = false;
    }

    function setFlashAuditDecision(decision = "approve") {
      const modal = document.querySelector('[data-modal="flash-audit"]');
      if (!modal) return;
      modal.dataset.flashAuditDecision = decision;
      modal.querySelectorAll("[data-flash-audit-decision]").forEach((button) => {
        const active = button.dataset.flashAuditDecision === decision;
        button.classList.toggle("is-active", active);
        button.classList.toggle("ant-radio-button-wrapper-checked", active);
      });
      const reasonField = modal.querySelector("[data-flash-audit-reason-field]");
      if (reasonField) reasonField.hidden = decision !== "reject";
      const submit = modal.querySelector("[data-flash-audit-submit]");
      if (submit) submit.textContent = decision === "reject" ? "确认拒绝" : "确认通过";
      const error = modal.querySelector("[data-flash-audit-error]");
      if (error) error.hidden = true;
    }

    function openFlashAuditModal(row) {
      const modal = document.querySelector('[data-modal="flash-audit"]');
      if (!row || !modal) return;
      activeFlashListRow = row;
      const object = modal.querySelector("[data-flash-audit-object]");
      if (object) object.textContent = `${row.dataset.contentId || "—"} · ${row.dataset.body || "—"}`;
      const reason = modal.querySelector("[data-flash-audit-reason]");
      if (reason) reason.value = "";
      setFlashAuditDecision("approve");
      document.querySelector(".modal-backdrop[data-close-layer]")?.classList.add("is-open");
      modal.classList.add("is-open");
      modal.setAttribute("aria-hidden", "false");
    }

    function submitFlashAudit() {
      const modal = document.querySelector('[data-modal="flash-audit"]');
      if (!modal || !activeFlashListRow) return false;
      const decision = modal.dataset.flashAuditDecision || "approve";
      const reason = modal.querySelector("[data-flash-audit-reason]")?.value?.trim() || "";
      const error = modal.querySelector("[data-flash-audit-error]");
      if (decision === "reject" && !reason) {
        if (error) {
          error.textContent = "请输入审核拒绝原因。";
          error.hidden = false;
        }
        return false;
      }
      const id = activeFlashListRow.dataset.contentId || "当前闪念";
      activeFlashListRow.dataset.filterStatus = decision === "reject" ? "审核失败" : "已发布";
      syncFlashListRow(activeFlashListRow);
      flashListFeedback(`${id} 已${decision === "reject" ? `拒绝：${reason}` : "审核通过"}；列表已刷新。`);
      activeFlashListRow = null;
      closeLayers();
      applyOperationalFilters("flash-management");
      return true;
    }

    function openFlashFeaturedModal(row) {
      const modal = document.querySelector('[data-modal="flash-featured"]');
      if (!row || !modal) return;
      activeFlashListRow = row;
      modal.querySelectorAll("[data-flash-featured-reason]").forEach((radio) => { radio.checked = false; });
      const error = modal.querySelector("[data-flash-featured-error]");
      if (error) error.hidden = true;
      document.querySelector(".modal-backdrop[data-close-layer]")?.classList.add("is-open");
      modal.classList.add("is-open");
      modal.setAttribute("aria-hidden", "false");
    }

    function submitFlashFeatured() {
      const modal = document.querySelector('[data-modal="flash-featured"]');
      if (!modal || !activeFlashListRow) return false;
      const reason = modal.querySelector("[data-flash-featured-reason]:checked")?.value || "";
      const error = modal.querySelector("[data-flash-featured-error]");
      if (!reason) {
        if (error) {
          error.textContent = "请选择精选理由。";
          error.hidden = false;
        }
        return false;
      }
      const id = activeFlashListRow.dataset.contentId || "当前闪念";
      activeFlashListRow.dataset.filterIsFeatured = "是";
      syncFlashListRow(activeFlashListRow);
      flashListFeedback(`${id} 已设为精选；理由 ${reason}。`);
      activeFlashListRow = null;
      closeLayers();
      applyOperationalFilters("flash-management");
      return true;
    }

    function syncFlashListRow(row) {
      if (!row) return;
      const id = row.dataset.contentId || "";
      const status = row.dataset.filterStatus || "草稿";
      const featured = row.dataset.filterIsFeatured || "否";
      const statusCell = row.querySelector("[data-flash-list-status-cell]") || row.children[5];
      const statusClass = status === "已发布" ? "tag success" : status === "审核中" ? "tag warning" : status === "审核失败" ? "tag danger" : "tag gray";
      if (statusCell) statusCell.innerHTML = `<span class="${statusClass}">${escapeHtml(status)}</span>`;
      const featuredCell = row.querySelector("[data-flash-list-featured-cell]") || row.children[7];
      if (featuredCell) featuredCell.innerHTML = featured === "是" ? '<span class="tag info">已精选</span>' : '<span class="muted">否</span>';
      const detail = `<a class="ant-btn ant-btn-link" href="flash-detail.html?id=${encodeURIComponent(id)}" data-flash-detail-link="${escapeAttribute(id)}" data-antd-component="Button">详情</a>`;
      const copy = '<button class="ant-btn ant-btn-link" type="button" data-flash-list-action="copy" data-antd-component="Button">复制 ID</button>';
      let stateActions = "";
      if (status === "审核中") stateActions = '<button class="ant-btn ant-btn-link" type="button" data-flash-list-action="audit" data-antd-component="Button">审核</button>';
      if (status === "审核失败") stateActions = `<button class="ant-btn ant-btn-link" type="button" data-flash-list-action="re-audit-pass" data-danger-action="flash-list-re-audit-pass" data-danger-object-id="${escapeAttribute(id)}" data-danger-current-state="审核失败" data-danger-result="复审通过" data-requires-confirm="true" data-antd-component="Button">复审通过</button>`;
      if (status === "已发布") stateActions = `${featured === "是" ? `<button class="ant-btn ant-btn-link" type="button" data-flash-list-action="cancel-featured" data-danger-action="flash-list-cancel-featured" data-danger-object-id="${escapeAttribute(id)}" data-danger-current-state="已精选" data-danger-result="取消精选" data-requires-confirm="true" data-antd-component="Button">取消精选</button>` : '<button class="ant-btn ant-btn-link" type="button" data-flash-list-action="set-featured" data-antd-component="Button">设为精选</button>'}<button class="ant-btn ant-btn-link" type="button" data-flash-list-action="unpublish" data-danger-action="flash-list-unpublish" data-danger-object-id="${escapeAttribute(id)}" data-danger-current-state="已发布" data-danger-result="下架内容" data-requires-confirm="true" data-antd-component="Button">下架</button>`;
      if (status === "已下架") stateActions = `<button class="ant-btn ant-btn-link" type="button" data-flash-list-action="publish" data-danger-action="flash-list-publish" data-danger-object-id="${escapeAttribute(id)}" data-danger-current-state="已下架" data-danger-result="恢复上架" data-requires-confirm="true" data-antd-component="Button">恢复</button>`;
      const remove = status === "已发布" || status === "审核中" ? "" : `<button class="ant-btn ant-btn-link ant-btn-dangerous" type="button" data-flash-list-action="delete" data-danger-action="flash-list-delete" data-danger-object-id="${escapeAttribute(id)}" data-danger-current-state="${escapeAttribute(status)}" data-danger-result="删除内容" data-requires-confirm="true" data-antd-component="Button">删除</button>`;
      const actionCell = row.children[9];
      if (actionCell) actionCell.innerHTML = `<div class="op-list">${detail}${copy}${stateActions}${remove}</div>`;
    }

    function syncRouteResolutionFeedback(view, { objectType, objectId, found, fallbackLabel = "当前列表", resolvedNote = "" }) {
      if (!view || !objectId) return false;
      let feedback = view.querySelector("[data-route-resolution-feedback]");
      if (!feedback) {
        feedback = document.createElement("div");
        feedback.className = "route-resolution-feedback";
        feedback.dataset.routeResolutionFeedback = "";
        feedback.setAttribute("role", "status");
        feedback.setAttribute("aria-live", "polite");
        feedback.hidden = true;
        const pageHead = view.querySelector(".page-head");
        if (pageHead) pageHead.insertAdjacentElement("afterend", feedback);
        else view.prepend(feedback);
      }
      const resolved = Boolean(found);
      view.dataset.routeResolution = resolved ? "resolved" : "missing";
      view.dataset.routeResolutionObjectType = objectType;
      view.dataset.routeResolutionObjectId = objectId;
      feedback.dataset.routeResolutionState = resolved && resolvedNote ? "corrected" : resolved ? "resolved" : "missing";
      feedback.hidden = resolved && !resolvedNote;
      feedback.textContent = resolvedNote
        ? resolvedNote
        : resolved
          ? ""
          : `未找到${objectType} ${objectId}。当前停留在${fallbackLabel}，没有打开、选中或继承其他对象；请检查来源链接，或返回列表重新选择。`;
      return resolved;
    }

    function syncReviewWorkbenchRouteContext() {
      const view = document.querySelector('.view.is-active[data-view="review-workbench"]');
      if (!view) return;
      const params = new URLSearchParams(window.location.search);
      const queue = params.get("queue");
      const taskId = params.get("task");
      const normalizedQueue = queue === "post" ? "post" : "work";
      activateReviewTab(normalizedQueue);
      if (!taskId) return;
      const row = [...view.querySelectorAll('tr[data-review-queue]')].find((item) => item.dataset.reviewObjectId === taskId);
      if (row) openReviewAuditModal(row.querySelector("[data-open-review-audit]"));
      else syncRouteResolutionFeedback(view, { objectType: normalizedQueue === "post" ? "闪念" : "作品", objectId: taskId, found: false, fallbackLabel: "审核工作台" });
    }

    function getReviewTaskCatalog() {
      const node = document.querySelector("script[data-review-task-catalog]");
      if (!node) return [];
      try {
        return JSON.parse(node.textContent || "[]");
      } catch {
        return [];
      }
    }

    function normalizeReviewTaskLinks() {
      document.querySelectorAll('a[href^="review-detail.html"]').forEach((link) => {
        link.href = "review-workbench.html";
      });
    }

    function normalizeSingleObjectWorkspaceEntries() {
      const normalizeRows = (selector, drawerType, workspaceName) => {
        document.querySelectorAll(selector).forEach((row) => {
          const triggers = [...row.querySelectorAll(`[data-open-drawer="${drawerType}"]`)];
          if (!triggers.length) return;
          const editTrigger = triggers.find((trigger) => trigger.dataset.drawerIntent === "edit") || triggers[0];
          triggers.forEach((trigger) => {
            if (trigger !== editTrigger) trigger.remove();
          });
          editTrigger.dataset.drawerIntent = "edit";
          editTrigger.dataset.objectWorkspace = workspaceName;
          editTrigger.dataset.objectEntryContract = "single-workspace";
          editTrigger.textContent = "编辑";
          editTrigger.setAttribute("aria-label", `编辑${workspaceName}`);
        });
      };
      normalizeRows("[data-model-row]", "model-detail", "模型");
      normalizeRows("[data-store-catalog-item]", "store-detail", "商品");
    }

    function normalizeObjectEntryResponsibilities() {
      const applyEntryContract = (selector, label, contract, ariaLabel) => {
        document.querySelectorAll(selector).forEach((entry) => {
          entry.textContent = label;
          entry.dataset.objectEntryContract = contract;
          entry.setAttribute("aria-label", ariaLabel);
        });
      };

      applyEntryContract('[data-table="activity-workbench"] [data-open-view="activity-detail"]', "进入活动", "task-page", "进入活动运营工作页");
      applyEntryContract('[data-table="activity-workbench"] [data-open-growth-modal="activity-edit"]', "编辑展示", "scoped-edit", "编辑 C端标题、封面和活动正文");
      applyEntryContract('[data-table="user-list"] [data-open-view="user-detail"]', "用户详情", "task-page", "进入用户详情工作页");
      applyEntryContract('[data-table="invite-records"] [data-open-drawer="invite-detail"]', "邀请详情", "independent-readonly", "查看邀请记录详情");
      applyEntryContract('[data-table="role-management"] [data-open-drawer="role-detail"][data-drawer-intent="edit"]', "调整权限", "direct-save-edit", "调整并保存角色权限");
      applyEntryContract('[data-table="admin-users"] [data-open-drawer="admin-user-detail"][data-drawer-intent="edit"]', "编辑", "direct-save-edit", "查看并编辑后台用户账号资料与角色");
    }

    function syncApprovedCEndContracts() {
      const contentTask = document.querySelector('[data-review-object-id="AIGC-1005"]');
      if (contentTask) contentTask.dataset.reviewSourcePageState = "落点可用";

      const commentTask = document.querySelector('[data-review-object-id="COM-3098"]');
      if (commentTask) {
        commentTask.dataset.reviewSourcePage = "flash.html?flash=FLA-0307&comment=COM-3098#comment-COM-3098";
        commentTask.dataset.reviewSourcePageState = "落点可用";
        commentTask.dataset.reviewSourcePageLabel = "闪念 FLA-0307 · 评论 COM-3098";
        commentTask.dataset.reviewSourceBendHref = "flash-detail.html?id=FLA-0307";
        commentTask.dataset.reviewSourceBendState = "已登记";
        commentTask.dataset.reviewPublicStateLabel = "未通过 · C端仅作者可见";
        commentTask.dataset.reviewNextStep = "引导用户去掉联系方式后修改并重新提交；来源闪念保持原状态";
      }

    }

    function syncReviewDetailPage() {
      const view = document.querySelector('.view[data-view="review-detail"]');
      if (!view) return;
      const params = new URLSearchParams(window.location.search);
      const requestedTaskId = params.get("task") || "";
      const catalog = getReviewTaskCatalog();
      const task = requestedTaskId ? catalog.find((item) => item.taskId === requestedTaskId) : catalog[0];
      const setText = (selector, value) => {
        const node = view.querySelector(selector);
        if (node) node.textContent = value || "待补充";
      };
      if (!task) {
        syncRouteResolutionFeedback(view, { objectType: "审核任务", objectId: requestedTaskId || "未提供", found: false, fallbackLabel: "审核任务详情" });
        view.querySelector("[data-review-page-actionable]").hidden = true;
        view.querySelector("[data-review-page-readonly]").hidden = false;
        const nextTaskLink = view.querySelector("[data-review-page-next-task]");
        if (nextTaskLink) {
          nextTaskLink.removeAttribute("href");
          nextTaskLink.textContent = "暂无下一条";
          nextTaskLink.classList.add("is-disabled");
          nextTaskLink.setAttribute("aria-disabled", "true");
        }
        return;
      }
      view.dataset.reviewTaskId = task.taskId;
      view.dataset.reviewQueue = task.queue;
      activeReviewContext = { ...task, row: null };
      setText("[data-review-page-task-id]", task.taskId);
      setText("[data-review-page-title]", `${task.objectType}审核 · ${task.summary}`);
      setText("[data-review-page-subtitle]", `${task.taskId} · ${task.status} · ${task.nextStep}`);
      setText("[data-review-page-status]", task.status);
      setText("[data-review-page-sla]", task.sla);
      setText("[data-review-page-object]", `${task.objectId} · ${task.summary}`);
      setText("[data-review-page-people]", `${task.submitter} · 处理人 ${task.assignee}`);
      setText("[data-review-page-risk-source]", task.riskSource);
      setText("[data-review-page-risk-summary]", task.riskSummary);
      setText("[data-review-page-source-state]", task.sourceBendState || task.sourcePageState);
      setText("[data-review-page-source-object]", task.sourceObjectId || task.objectId || "未登记");
      setText("[data-review-page-source-cend]", task.sourcePageLabel || "来源页面");
      setText("[data-review-page-public-state]", task.publicStateLabel || task.publicState || "待确认");
      const relatedRecords = [task.activityId, task.activityRecordId, task.ruleVersion, task.resultLogId].filter(Boolean).join(" · ");
      setText("[data-review-page-related-records]", relatedRecords);
      const relatedRow = view.querySelector("[data-review-page-related-row]");
      if (relatedRow) relatedRow.hidden = !relatedRecords;
      setText("[data-review-page-submitted-at]", task.submittedAt);
      setText("[data-review-page-history-status]", task.status);
      setText("[data-review-page-second-review]", task.secondReview);
      setText("[data-review-page-next-step]", task.nextStep);
      const status = view.querySelector("[data-review-page-status]");
      if (status) status.className = tagClassForText(task.status);
      const sourceState = view.querySelector("[data-review-page-source-state]");
      if (sourceState) sourceState.className = task.sourceBendHref ? "tag success" : "tag warning";
      const sourceLink = view.querySelector("[data-review-page-source-link]");
      if (sourceLink) {
        sourceLink.hidden = !task.sourceBendHref;
        if (task.sourceBendHref) sourceLink.href = task.sourceBendHref;
      }
      view.querySelectorAll("[data-review-back-link]").forEach((link) => {
        link.href = `${pageRoutes["review-workbench"] || "review-workbench.html"}?queue=${encodeURIComponent(task.queue)}`;
      });
      const queueTasks = catalog.filter((item) => item.queue === task.queue);
      const currentQueueIndex = queueTasks.findIndex((item) => item.taskId === task.taskId);
      const nextTask = currentQueueIndex >= 0 ? queueTasks[currentQueueIndex + 1] : null;
      const nextTaskLink = view.querySelector("[data-review-page-next-task]");
      if (nextTaskLink) {
        if (nextTask) {
          nextTaskLink.href = `review-workbench.html?queue=${encodeURIComponent(task.queue)}&task=${encodeURIComponent(nextTask.taskId)}`;
          nextTaskLink.textContent = "下一条";
          nextTaskLink.classList.remove("is-disabled");
          nextTaskLink.removeAttribute("aria-disabled");
          nextTaskLink.setAttribute("aria-label", `下一条：${nextTask.summary}`);
        } else {
          nextTaskLink.removeAttribute("href");
          nextTaskLink.textContent = "已是最后一条";
          nextTaskLink.classList.add("is-disabled");
          nextTaskLink.setAttribute("aria-disabled", "true");
          nextTaskLink.removeAttribute("aria-label");
        }
      }
      const userReason = view.querySelector("[data-review-page-user-reason]");
      const internalNote = view.querySelector("[data-review-page-internal-note]");
      if (userReason) userReason.value = task.userReason === "待填写" ? "" : task.userReason;
      if (internalNote) internalNote.value = task.internalNote || "";
      const actionable = /待审核|复核中/.test(task.status);
      view.querySelector("[data-review-page-actionable]").hidden = !actionable;
      view.querySelector("[data-review-page-readonly]").hidden = actionable;
      setText("[data-review-page-mode]", actionable ? "可处理" : "只读回查");
      const returnEdit = view.querySelector('[data-review-page-decision="return-edit"]');
      if (returnEdit) returnEdit.hidden = task.queue === "comment";
      view.querySelectorAll("[data-review-page-decision]").forEach((button) => {
        const decision = button.dataset.reviewPageDecision;
        button.dataset.dangerAction = `review-${decision}`;
        button.dataset.dangerObjectId = `${task.taskId} / ${task.objectId}`;
        button.dataset.dangerCurrentState = `${task.status} · ${task.summary}`;
        button.dataset.dangerResult = `保存${decision === "approve" ? "通过" : decision === "reject" ? "拒绝" : decision === "second-review" ? "转复核" : "退回修改"}结论；用户可读结果与内部备注分开记录，并生成可回查日志`;
        button.dataset.requiresConfirm = "true";
        button.dataset.requiresReason = "true";
      });
      syncRouteResolutionFeedback(view, { objectType: "审核任务", objectId: requestedTaskId || task.taskId, found: task.taskId === (requestedTaskId || task.taskId), fallbackLabel: "审核任务详情" });
    }

    function syncStickyActionColumns(root = document) {
      root.querySelectorAll(".table-wrap").forEach((wrapper) => {
        const lastHeader = wrapper.querySelector("thead th:last-child");
        wrapper.toggleAttribute("data-sticky-action-column", lastHeader?.textContent?.trim() === "操作");
      });
    }

    function activateSlotTab(slotType) {
      const view = document.querySelector('.view[data-view="home-slots"]');
      if (!view || !slotType) return;
      const isDiamondArea = slotType === "home-diamond-area";
      const isHomeTopCampaign = slotType === "top-campaign";
      const isModelOperationCard = slotType === "model-operation-card";
      view.dataset.activeSlotContract = isDiamondArea ? "preset-navigation" : "source-delivery";
      view.querySelectorAll("[data-slot-tab]").forEach((tab) => {
        const isActive = tab.dataset.slotTab === slotType;
        tab.classList.toggle("is-active", isActive);
        tab.setAttribute("aria-selected", isActive ? "true" : "false");
      });
      const operationPanels = view.querySelectorAll('[data-slot-panel="operation-slots"]');
      const diamondPanel = view.querySelector('[data-slot-panel="home-diamond-area"]');
      operationPanels.forEach((operationPanel) => {
        operationPanel.hidden = isDiamondArea;
      });
      if (diamondPanel) diamondPanel.hidden = !isDiamondArea;
      const createButton = view.querySelector("[data-slot-create-action]");
      if (createButton) createButton.hidden = isDiamondArea;
      const stateTitle = view.querySelector("[data-slot-summary-state-title]");
      const stateBody = view.querySelector("[data-slot-summary-state-body]");
      const guardTitle = view.querySelector("[data-slot-summary-guard-title]");
      const guardBody = view.querySelector("[data-slot-summary-guard-body]");
      const contractPanel = view.querySelector("[data-slot-contract-panel]");
      if (isDiamondArea) {
        if (stateTitle) stateTitle.textContent = "入口状态";
        if (stateBody) stateBody.innerHTML = '<span class="tag success">启用</span> <span class="tag warning">停用</span>';
        if (guardTitle) guardTitle.textContent = "目标页校验";
        if (guardBody) guardBody.textContent = "只允许已登记的 C端页面与页内位置；页面或锚点不可用时不得启用。";
        if (contractPanel) contractPanel.textContent = "首页金刚区是产品预置功能入口，只允许编辑现有入口；后台不可新增或删除。启停必须填写原因，并明确 C端展示结果。";
      } else {
        if (stateTitle) stateTitle.textContent = "投放生命周期";
        if (stateBody) stateBody.innerHTML = '<span class="tag gray">草稿</span> <span class="tag info">待生效</span> <span class="tag success">展示中</span> <span class="tag warning">已暂停</span> <span class="tag gray">已结束</span> <span class="tag danger">已失效</span>';
        if (guardTitle) guardTitle.textContent = "绑定校验";
        if (guardBody) guardBody.textContent = "业务来源失效时投放失效；跳转链接支持站内相对路径或 HTTPS 站外地址。";
        if (contractPanel) {
          contractPanel.textContent = isHomeTopCampaign
            ? "这里只管理首页 index.html 的顶部限时条；其他页面复用同一视觉类名的上下文提示不属于一条全站投放。"
            : isModelOperationCard
              ? "模型广场 Hero 是模型供给与产品信息主区，不是运营广告位；本页只管理 Hero 下方 2 张模型广场运营卡。"
              : "展示位由产品预置，后台只管理投放单；投放可绑定业务来源对象，并配置站内相对路径或 HTTPS 站外链接。只有业务来源对象使用来源失效—恢复合同，链接型投放只校验地址格式与可用性。";
        }
      }
      view.querySelectorAll('[data-table="home-slots"] tbody tr').forEach((row) => {
        const isActiveSlotType = row.dataset.slotType === slotType;
        row.hidden = isDiamondArea || !isActiveSlotType;
        row.classList.toggle("is-slot-focused", isActiveSlotType);
      });
      const showBackgroundColumn = !isDiamondArea && slotNeedsBackground(slotType);
      view.querySelectorAll("[data-slot-background-col], [data-slot-background-column], [data-slot-background-cell]").forEach((node) => {
        node.hidden = !showBackgroundColumn;
      });
    }

    function normalizeHomeSlotActions() {
      const legacyView = document.querySelector('.view[data-view="home-slots"]:not([data-b03-page])');
      if (!legacyView) return;
      const createButton = legacyView.querySelector('.page-head .action-row .btn.primary');
      if (createButton) {
        createButton.removeAttribute("data-open-drawer");
        createButton.dataset.openSlotModal = "create";
        createButton.textContent = "新建投放";
      }
      legacyView.querySelectorAll('[data-table="home-slots"] tbody tr').forEach((row) => {
        if (!row.dataset.slotId) row.dataset.slotId = getCellText(row, 0);
        syncSlotRowMetadata(row);
        syncSlotDeliveryState(row);
        const actionCell = row.children[row.children.length - 1];
        if (actionCell) actionCell.innerHTML = slotActionMarkup(row);
      });
      const activeTab = legacyView.querySelector('[data-slot-tab].is-active')?.dataset.slotTab || "home-banner";
      activateSlotTab(activeTab);
    }

