    function getActivityDatasetValue(row, field) {
      const key = activityDatasetMap[field];
      return key ? row?.dataset?.[key] || "" : "";
    }

    function setActivityDatasetValues(row, values) {
      Object.entries(activityDatasetMap).forEach(([field, datasetKey]) => {
        row.dataset[datasetKey] = values[field] || "";
      });
    }

    function renderActivityTypeTag(value) {
      return `<span class="tag info">${activityTypeLabel(value)}</span>`;
    }

