        author: `${record.authorName} ${record.authorId}`.trim(),
        state: record.state || "已发布",
        source: "首页爆款作品",
        homeHot: `首页爆款 #${record.order}`,
        published: record.publishedAt,
        operator: "系统同步",
        tags: [record.type, record.model, "首页爆款作品"].filter(Boolean),
        summary: record.summary,
        prompt: `C端当前卡片只确认了摘要“${record.summary}”，并统一落到 ${record.detailTarget || "待回查"}；该卡片的独立详情正文尚无权威需求来源，后台不补造。`,
        media: record.media || "",
        metrics: { like: "—", favorite: "—", comment: "—" },
        activity: "",
        pointsRule: "",
        pointsNote: "",
        lifecycle: "published",
