    function activateContentDetailTab(tabName = "prompt") {
      const view = document.querySelector('.view[data-view="content-detail"]');
      if (!view) return;
      view.querySelectorAll("[data-detail-tab]").forEach((tab) => {
        const isActive = tab.dataset.detailTab === tabName;
        tab.classList.toggle("is-active", isActive);
        tab.classList.toggle("detail-tab-label-muted", !isActive);
        tab.setAttribute("aria-selected", isActive ? "true" : "false");
      });
      view.querySelectorAll("[data-detail-panel]").forEach((panel) => {
        panel.hidden = panel.dataset.detailPanel !== tabName;
      });
    }

    function activateBusinessTab(button) {
      const tabGroup = button?.closest("[data-business-tabs]");
      const view = button?.closest(".view");
      if (!tabGroup || !view) return;
      const groupName = tabGroup.dataset.businessTabs;
      const tabName = button.dataset.businessTab;
      tabGroup.querySelectorAll("[data-business-tab]").forEach((tab) => {
        const isActive = tab.dataset.businessTab === tabName;
        tab.classList.toggle("is-active", isActive);
        tab.setAttribute("aria-selected", isActive ? "true" : "false");
      });
      view.querySelectorAll(`[data-business-panel-group="${groupName}"]`).forEach((panel) => {
        panel.hidden = panel.dataset.businessPanel !== tabName;
      });
    }

    function syncRouteTabContext() {
      const params = new URLSearchParams(window.location.search);
      const activeView = document.querySelector(".view.is-active");
      const tab = params.get("tab") || "";
      if (activeView?.dataset.view === "operation-log") {
        const logId = params.get("log") || "";
        if (logId) {
          activeView.querySelectorAll('table[data-table="operation-log"] tbody tr[data-route-target]').forEach((row) => delete row.dataset.routeTarget);
          const logRow = [...activeView.querySelectorAll('table[data-table="operation-log"] tbody tr[data-operational-filter-row]')]
            .find((row) => row.children[0]?.textContent?.trim() === logId);
          if (logRow) {
            logRow.dataset.routeTarget = "true";
            logRow.scrollIntoView({ block: "center" });
          }
          syncRouteResolutionFeedback(activeView, { objectType: "操作日志", objectId: logId, found: Boolean(logRow), fallbackLabel: "操作日志列表" });
        }
      }
      if (activeView?.dataset.view === "activity-detail") {
        const activityTabs = ["base", "display", "eligibility", "tasks", "submissions", "rewards", "records", "grants", "settlement", "changes"];
        const rewardId = params.get("reward") || "";
        const recordId = rewardId ? "" : params.get("record") || "";
        const requestedActivityId = activeView.dataset.routeRequestedActivityId || params.get("id") || "";
        const resolvedActivityId = activeView.dataset.activityDetailId || "";
        const activityContextCorrected = activeView.dataset.routeActivityContextCorrected === "true";
        if (activityTabs.includes(tab) && !(tab === "grants" && rewardId) && !(tab === "records" && recordId)) {
          const activityTab = activeView.querySelector(`[data-business-tab="${CSS.escape(tab)}"]`);
          if (activityTab && !activityTab.hidden) activateBusinessTab(activityTab);
        }
        if (rewardId && activeView.dataset.runtimeActivityContext === "known") {
          activeView.querySelectorAll("[data-activity-reward-row][data-route-target]").forEach((row) => delete row.dataset.routeTarget);
          const rewardRow = activeView.querySelector(`[data-activity-reward-row][data-reward-id="${CSS.escape(rewardId)}"]`);
          if (rewardRow) {
            const rewardTab = activeView.querySelector('[data-business-tab="grants"]');
            if (rewardTab) activateBusinessTab(rewardTab);
            rewardRow.dataset.routeTarget = "true";
            rewardRow.scrollIntoView({ block: "center" });
            syncRouteResolutionFeedback(activeView, {
              objectType: "奖励记录",
              objectId: rewardId,
              found: true,
              fallbackLabel: "当前活动",
              resolvedNote: activityContextCorrected
                ? `奖励记录 ${rewardId} 实际归属活动 ${resolvedActivityId}，已从链接中的 ${requestedActivityId} 切换到真实活动并定位奖励处理记录。`
                : "",
            });
          } else {
            const baseTab = activeView.querySelector('[data-business-tab="base"]');
            if (baseTab) activateBusinessTab(baseTab);
            syncRouteResolutionFeedback(activeView, { objectType: "奖励记录", objectId: rewardId, found: false, fallbackLabel: "当前活动基础信息" });
          }
        }
        if (recordId && activeView.dataset.runtimeActivityContext === "known") {
          activeView.querySelectorAll("[data-activity-record-row][data-route-target]").forEach((row) => delete row.dataset.routeTarget);
          const recordRow = activeView.querySelector(`[data-activity-record-row][data-activity-record-id="${CSS.escape(recordId)}"]`);
          if (recordRow) {
            const recordsTab = activeView.querySelector('[data-business-tab="records"]');
            if (recordsTab) activateBusinessTab(recordsTab);
            recordRow.dataset.routeTarget = "true";
            recordRow.scrollIntoView({ block: "center" });
            syncRouteResolutionFeedback(activeView, {
              objectType: "活动记录",
              objectId: recordId,
              found: true,
              fallbackLabel: "当前活动",
              resolvedNote: activityContextCorrected
                ? `活动记录 ${recordId} 实际归属活动 ${resolvedActivityId}，已从链接中的 ${requestedActivityId} 切换到真实活动并定位参与投稿记录。`
                : "",
            });
          } else {
            const baseTab = activeView.querySelector('[data-business-tab="base"]');
            if (baseTab) activateBusinessTab(baseTab);
            syncRouteResolutionFeedback(activeView, { objectType: "活动记录", objectId: recordId, found: false, fallbackLabel: "当前活动基础信息" });
          }
        }
      }
      if (activeView?.dataset.view === "home-slots") {
        const slotId = params.get("slot") || "";
        const slotRow = slotId ? activeView.querySelector(`[data-slot-id="${CSS.escape(slotId)}"]`) : null;
        if (slotRow) {
          activeView.querySelectorAll("[data-slot-id][data-route-target]").forEach((row) => delete row.dataset.routeTarget);
          activateSlotTab(slotRow.dataset.slotType || "home-banner");
          slotRow.dataset.routeTarget = "true";
          slotRow.scrollIntoView({ block: "center" });
          openSlotModal("edit", slotRow);
        }
        if (slotId) syncRouteResolutionFeedback(activeView, { objectType: "投放记录", objectId: slotId, found: Boolean(slotRow), fallbackLabel: "展示位列表" });
      }
      if (activeView?.dataset.view === "model-management") {
        const modelId = params.get("model") || "";
        const modelRow = modelId ? activeView.querySelector(`[data-model-row][data-model-id="${CSS.escape(modelId)}"]`) : null;
        const detailTrigger = modelRow?.querySelector('[data-open-drawer="model-detail"][data-drawer-intent="edit"]');
        if (modelRow && detailTrigger) {
          activeView.querySelectorAll("[data-model-row][data-route-target]").forEach((row) => delete row.dataset.routeTarget);
          modelRow.dataset.routeTarget = "true";
          modelRow.scrollIntoView({ block: "center" });
          openDrawer("model-detail", detailTrigger);
        }
        if (modelId) syncRouteResolutionFeedback(activeView, { objectType: "模型", objectId: modelId, found: Boolean(modelRow && detailTrigger), fallbackLabel: "模型列表" });
      }
      if (activeView?.dataset.view === "store-config") {
        if (["items", "orders", "exceptions"].includes(tab)) {
          const storeTab = activeView.querySelector(`[data-business-tab="${CSS.escape(tab)}"]`);
          if (storeTab) activateBusinessTab(storeTab);
        }
        const recordId = params.get("record") || "";
        const productId = recordId ? "" : params.get("product") || "";
        const productRow = productId ? activeView.querySelector(`[data-store-sku-id="${CSS.escape(productId)}"]`) : null;
        const productTrigger = productRow?.querySelector('[data-open-drawer="store-detail"][data-drawer-intent="edit"]');
        if (productRow && productTrigger) {
          const itemsTab = activeView.querySelector('[data-business-tab="items"]');
          if (itemsTab) activateBusinessTab(itemsTab);
          activeView.querySelectorAll("[data-store-sku-id][data-route-target]").forEach((row) => delete row.dataset.routeTarget);
          productRow.dataset.routeTarget = "true";
          productRow.scrollIntoView({ block: "center" });
          openDrawer("store-detail", productTrigger);
        }
        if (productId) syncRouteResolutionFeedback(activeView, { objectType: "商城商品", objectId: productId, found: Boolean(productRow && productTrigger), fallbackLabel: "商品列表" });
        if (recordId) {
          activeView.querySelectorAll("[data-redemption-remediation][data-route-target]").forEach((card) => delete card.dataset.routeTarget);
          const recordCard = activeView.querySelector(`[data-redemption-remediation="${CSS.escape(recordId)}"]`);
          if (recordCard) {
            const exceptionsTab = activeView.querySelector('[data-business-tab="exceptions"]');
            if (exceptionsTab) activateBusinessTab(exceptionsTab);
            recordCard.dataset.routeTarget = "true";
            recordCard.scrollIntoView({ block: "center" });
          }
          syncRouteResolutionFeedback(activeView, { objectType: "兑换异常记录", objectId: recordId, found: Boolean(recordCard), fallbackLabel: "异常处理列表" });
        }
      }
      if (activeView?.dataset.view === "role-management") {
        const roleId = params.get("role") || "";
        const roleRow = roleId ? activeView.querySelector(`[data-role-id="${CSS.escape(roleId)}"]`) : null;
        const adjustmentTrigger = roleRow?.querySelector('[data-open-drawer="role-detail"][data-drawer-intent="edit"]');
        if (roleRow && adjustmentTrigger) {
          activeView.querySelectorAll("[data-role-id][data-route-target]").forEach((row) => delete row.dataset.routeTarget);
          roleRow.dataset.routeTarget = "true";
          roleRow.scrollIntoView({ block: "center" });
          openDrawer("role-detail", adjustmentTrigger);
        }
        if (roleId) syncRouteResolutionFeedback(activeView, { objectType: "角色", objectId: roleId, found: Boolean(roleRow && adjustmentTrigger), fallbackLabel: "角色列表" });
      }
      if (activeView?.dataset.view === "user-list") {
        const accountState = activeView.querySelector('[data-operational-filter-control="account-state"]');
        const whitelistState = activeView.querySelector('[data-operational-filter-control="whitelist-state"]');
        if (tab === "enabled" && accountState) accountState.value = "正常";
        if (tab === "disabled" && accountState) accountState.value = "冻结";
        if (tab === "whitelist" && whitelistState) whitelistState.value = "启用";
        const recordId = params.get("record") || "";
        const userId = params.get("user") || ({ "WHT-001": "USR-1001", "WHT-002": "USR-9001" }[recordId] || "");
        activeView.querySelectorAll("[data-user-id][data-route-target]").forEach((row) => delete row.dataset.routeTarget);
        const targetRow = userId
          ? activeView.querySelector(`[data-user-id="${CSS.escape(userId)}"]`)
          : recordId
            ? activeView.querySelector(`[data-governance-record-id="${CSS.escape(recordId)}"]`)
            : null;
        if (targetRow) {
          targetRow.dataset.routeTarget = "true";
          targetRow.scrollIntoView({ block: "center" });
        }
        applyOperationalFilters("user-list");
        if (recordId || userId) syncRouteResolutionFeedback(activeView, { objectType: "用户账号", objectId: recordId || userId, found: Boolean(targetRow), fallbackLabel: "用户列表" });
      }
      if (activeView?.dataset.view === "invite-records") {
        const recordId = params.get("record") || "";
        const recordRow = recordId ? activeView.querySelector(`[data-invite-record-id="${CSS.escape(recordId)}"]`) : null;
        const detailTrigger = recordRow?.querySelector('[data-open-drawer="invite-detail"]');
        if (detailTrigger) openDrawer("invite-detail", detailTrigger);
        if (recordId) syncRouteResolutionFeedback(activeView, { objectType: "邀请记录", objectId: recordId, found: Boolean(recordRow && detailTrigger), fallbackLabel: "邀请记录列表" });
      }
      if (activeView?.dataset.view === "points-records") {
        const entryId = params.get("entry") || "";
        const entryRow = entryId ? activeView.querySelector(`[data-points-record-id="${CSS.escape(entryId)}"]`) : null;
        if (entryRow) {
          activeView.querySelectorAll("[data-points-record-id][data-route-target]").forEach((row) => delete row.dataset.routeTarget);
          entryRow.dataset.routeTarget = "true";
          entryRow.scrollIntoView({ block: "center" });
        }
        if (entryId) syncRouteResolutionFeedback(activeView, { objectType: "限时积分流水", objectId: entryId, found: Boolean(entryRow), fallbackLabel: "限时积分流水列表" });
      }
    }

    function syncLegacyContentDetailActions(view) {
      if (!view) return;
      const contentId = view.dataset.runtimeContentId || "当前内容";
      const state = view.dataset.runtimeContentState || "";
      const homeHot = view.dataset.runtimeContentHomeHot || "未设置";
      const hotReward = view.dataset.runtimeContentHotReward || "";
      const lifecycle = view.querySelector('[data-content-op-action="lifecycle"]');
      const homeHotAction = view.querySelector('[data-content-op-action="home-hot"]');
      const reviewEntry = view.querySelector("[data-content-review-entry]");
      const note = view.querySelector("[data-content-detail-action-note]");
      const isPublished = state === "已发布";
      const isDown = state === "已下架";
      const isPending = /待审核|复核|退回|已拒绝|未通过/.test(state);
      const isReviewApproved = state === "审核通过" || state === "已通过";
      const hasHomeHot = !/未设置/.test(homeHot);
      const setDangerContract = (button, action, label, currentState, result, className) => {
        if (!button) return;
        button.hidden = false;
        button.disabled = false;
        button.className = className;
        button.textContent = label;
        button.dataset.dangerAction = action;
        button.dataset.dangerObjectId = contentId;
        button.dataset.dangerCurrentState = currentState;
        button.dataset.dangerResult = result;
      };
      if (lifecycle) lifecycle.hidden = true;
      if (homeHotAction) {
        homeHotAction.hidden = true;
        homeHotAction.textContent = hasHomeHot ? "取消首页爆款" : hotReward === "publish-points" ? "设为首页爆款并发放限时积分" : "设为首页爆款";
        homeHotAction.dataset.contentHotReward = hotReward;
      }
      if (reviewEntry) {
        reviewEntry.hidden = true;
        const reviewTaskId = view.dataset.runtimeContentReviewTaskId || "";
        const reviewQueue = view.dataset.runtimeContentReviewQueue || "";
        if (reviewTaskId && reviewQueue) {
          reviewEntry.href = `review-workbench.html?queue=${encodeURIComponent(reviewQueue)}&task=${encodeURIComponent(reviewTaskId)}`;
          reviewEntry.textContent = "返回审核任务";
        } else {
          reviewEntry.removeAttribute("href");
        }
      }
      if (isPublished) {
        setDangerContract(
          lifecycle,
          "content-take-down",
          "下架内容",
          `${state} · ${homeHot}`,
          "内容改为已下架；C端停止展示；首页爆款关系同步停止且恢复内容时不自动恢复；历史版本、互动和操作记录保留",
          "btn danger"
        );
        const hotLabel = hasHomeHot ? "取消首页爆款" : hotReward === "publish-points" ? "设为首页爆款并发放限时积分" : "设为首页爆款";
        const hotAction = hasHomeHot ? "content-home-hot-remove" : "content-home-hot-set";
        const hotResult = hasHomeHot
          ? "取消首页爆款关系；内容保持已发布；历史精选关系和操作日志保留"
          : `新增首页爆款关系；内容保持已发布${hotReward === "publish-points" ? "；同步新增 +30 发布限时积分记录" : ""}；写入操作日志`;
        setDangerContract(homeHotAction, hotAction, hotLabel, `${state} · ${homeHot}`, hotResult, hasHomeHot ? "btn danger" : "btn primary");
        if (homeHotAction) homeHotAction.dataset.contentHotReward = hotReward;
        if (note) note.textContent = "内容已发布，可管理 C端展示和首页爆款关系；两类动作互不替代。";
      } else if (isDown) {
        setDangerContract(
          lifecycle,
          "content-restore",
          "恢复内容",
          `${state} · ${homeHot}`,
          "内容改为已发布；C端恢复展示；原首页爆款关系不自动恢复；历史版本、互动和操作记录保留",
          "btn primary"
        );
        if (note) note.textContent = "内容已下架，仅允许恢复展示；恢复后不会自动恢复首页爆款关系。";
      } else if (isPending) {
        if (reviewEntry && reviewEntry.hasAttribute("href")) reviewEntry.hidden = false;
        if (note) note.textContent = reviewEntry?.hasAttribute("href")
          ? "当前内容尚未完成审核；可返回精确审核任务核对结论，通过并发布后才可管理 C端展示和首页爆款关系。"
          : "当前内容尚未完成审核且审核任务未登记；先回查来源关系，不提供泛化审核入口。";
      } else if (isReviewApproved) {
        const activityId = view.dataset.runtimeContentActivityId || "关联活动";
        const activityRecordId = view.dataset.runtimeContentActivityRecordId || "活动记录";
        if (reviewEntry && reviewEntry.hasAttribute("href")) reviewEntry.hidden = false;
        if (note) note.textContent = `来源审核已完成；活动资格仍须在 ${activityId} / ${activityRecordId} 独立判定，内容发布状态按内容流程另行处理。`;
      } else {
        if (note) note.textContent = "当前状态仅供核对，不提供恢复或精选动作；如需处理请回到对应业务工作台。";
      }
    }

    function syncContentVersionSummary(view) {
      if (!view) return;
      const state = view.dataset.runtimeContentState || "";
      const currentVersion = view.dataset.runtimeContentVersionCurrent || "";
      const pendingVersion = view.dataset.runtimeContentVersionPending || "";
      const pendingNote = view.dataset.runtimeContentVersionPendingNote || "";
      const currentNode = view.querySelector("[data-content-detail-version-current]");
      const pendingNode = view.querySelector("[data-content-detail-version-pending]");
      if (currentNode) {
        if (!currentVersion) {
          currentNode.textContent = "当前公开版本：无";
        } else if (state === "已下架") {
          currentNode.textContent = `当前可恢复版本：${currentVersion} · 已下架，C端不可见`;
        } else if (state === "已发布") {
          currentNode.textContent = `当前公开版本：${currentVersion} · 已发布`;
        } else {
          currentNode.textContent = `当前版本：${currentVersion} · ${state || "待确认"}`;
        }
      }
      if (pendingNode) {
        if (!pendingVersion) {
          pendingNode.textContent = "待审版本：无";
        } else {
          const pendingLabel = state === "审核通过" || state === "已通过"
            ? "待发布版本"
            : state === "已拒绝"
              ? "未通过版本"
              : "待审版本";
          const visibilityNote = state === "已下架"
            ? "；当前无公开版本"
            : state === "已发布" && currentVersion
              ? `，${currentVersion} 继续公开`
              : "";
          pendingNode.textContent = `${pendingLabel}：${pendingVersion}${pendingNote ? ` · ${pendingNote}` : ""}${visibilityNote}`;
        }
      }
    }

    function syncLegacyContentDetailPage() {
      const view = document.querySelector('.view[data-view="content-detail"]');
      if (!view) return;
      const currentId = new URLSearchParams(window.location.search).get("id") || "AIGC-1001";
      const currentCatalogSamples = getCurrentCEndContentDetailSamples();
      const knownItem = contentDetailSamples[currentId] || currentCatalogSamples[currentId];
      const sourceItem = knownItem || missingContentDetailSample(currentId);
      const reviewHandoff = getSubmissionReviewHandoff(sourceItem.reviewTaskId || "");
      const pendingVersionNoteMap = {
        approved: "Prompt 投稿审核已通过，待发布",
        rejected: "Prompt 投稿审核未通过",
        "second-review": "Prompt 投稿复核中",
        returned: "等待用户修改并重新提交",
      };
      const item = reviewHandoff
        ? {
            ...sourceItem,
            state: reviewHandoff.statusLabel,
            lifecycle: `review-${reviewHandoff.decision}`,
            pendingVersionNote: pendingVersionNoteMap[reviewHandoff.decision] || sourceItem.pendingVersionNote,
            tags: (sourceItem.tags || []).map((tag) => /待审核|已拒绝|审核通过|复核中|退回修改/.test(tag) ? reviewHandoff.statusLabel : tag),
          }
        : sourceItem;
      view.dataset.runtimeContentContext = knownItem ? (currentCatalogSamples[currentId] ? "current-cend-catalog" : "operation-sample") : "unknown";
      view.dataset.runtimeContentId = item.id;
      view.dataset.runtimeContentState = item.state;
      view.dataset.runtimeContentHomeHot = item.homeHot || "未设置";
      view.dataset.runtimeContentHotReward = item.hotReward || "";
      view.dataset.runtimeContentVersionCurrent = item.currentVersion || "";
      view.dataset.runtimeContentVersionPending = item.pendingVersion || "";
      view.dataset.runtimeContentVersionPendingNote = item.pendingVersionNote || "";
      view.dataset.runtimeContentActivityId = item.activityId || "";
      view.dataset.runtimeContentActivityRecordId = item.activityRecordId || "";
      view.dataset.runtimeContentReviewTaskId = item.reviewTaskId || "";
      view.dataset.runtimeContentReviewQueue = item.reviewQueue || "";
      view.dataset.runtimeContentRuleVersion = item.ruleVersion || "";
      view.dataset.runtimeContentDetailTarget = item.detailTarget || "";
      view.dataset.contentLifecycle = item.lifecycle || "unknown";
      view.querySelectorAll("[data-content-detail-title]").forEach((node) => { node.textContent = item.title; });
      const setText = (selector, value) => {
        const node = view.querySelector(selector);
        if (node) node.textContent = value;
      };
      setText("[data-content-detail-summary]", item.summary);
      setText("[data-content-detail-prompt]", item.prompt);
      setText("[data-content-detail-id]", item.id);
      setText("[data-content-detail-author]", item.author);
      setText("[data-content-detail-source-text]", item.source);
      setText("[data-content-detail-published]", item.published);
      setText("[data-content-detail-operator]", item.operator);
      setText("[data-content-detail-like]", item.metrics.like);
      setText("[data-content-detail-favorite]", item.metrics.favorite);
      setText("[data-content-detail-comment]", item.metrics.comment);
      setText("[data-content-detail-activity-name]", item.activity || "");
      setText("[data-content-detail-activity-id]", item.activityId || "");
      setText("[data-content-detail-activity-record-id]", item.activityRecordId || "");
      setText("[data-content-detail-review-task-id]", item.reviewTaskId || "");
      setText("[data-content-detail-rule-version]", item.ruleVersion || "");
      setText("[data-content-detail-points-rule]", item.pointsRule || "");
      setText("[data-content-detail-points-note]", item.pointsNote || "");
      setText("[data-content-detail-manga-product]", item.crossProduct?.product || "");
      setText("[data-content-detail-manga-work]", item.crossProduct?.sourceWork || "");
      setText("[data-content-detail-manga-confirm]", item.crossProduct?.publishConfirm || "");
      setText("[data-content-detail-manga-reward]", item.crossProduct?.rewardState || "");
      setText("[data-content-detail-manga-dedupe]", item.crossProduct?.dedupe || "");
      setText("[data-content-detail-manga-fallback]", item.crossProduct?.fallback || "");
      setText("[data-content-detail-feature-relation]", item.featureRelation || "未设置");
      const detailMedia = view.querySelector(".case-detail-media img.case-gallery-main");
      const detailMediaEmpty = view.querySelector("[data-content-detail-media-empty]");
      const hasRegisteredMedia = Boolean(item.media);
      if (detailMedia) {
        detailMedia.alt = item.title;
        detailMedia.hidden = !hasRegisteredMedia;
        if (hasRegisteredMedia) detailMedia.src = item.media;
        else detailMedia.removeAttribute("src");
      }
      if (detailMediaEmpty) detailMediaEmpty.hidden = hasRegisteredMedia;
      const tags = view.querySelector("[data-content-detail-tags]");
      if (tags) tags.innerHTML = item.tags.map((tag) => `<span>${tag}</span>`).join("");
      const state = view.querySelector("[data-content-detail-state]");
      if (state) state.innerHTML = `<span class="${tagClassForText(item.state)}">${item.state}</span>`;
      const homeHot = view.querySelector("[data-content-detail-home-hot]");
      if (homeHot) {
        const value = item.homeHot || "未设置";
        const className = /未设置/.test(value) ? "tag gray" : tagClassForText(value);
        homeHot.innerHTML = `<span class="${className}">${value}</span>`;
      }
      syncContentVersionSummary(view);
      const activityPanel = view.querySelector("[data-content-detail-activity-panel]");
      if (activityPanel) activityPanel.hidden = !item.activity;
      const mangaReturnPanel = view.querySelector("[data-content-detail-manga-return-panel]");
      if (mangaReturnPanel) mangaReturnPanel.hidden = !item.crossProduct;
      const feedback = view.querySelector("[data-content-detail-action-feedback]");
      if (feedback) feedback.hidden = true;
      const comments = view.querySelector("[data-content-detail-comments]");
      if (comments) {
        comments.innerHTML = `<b>评论列表</b>${(item.comments || []).map(([name, text, meta, initial]) => `
          <div class="flash-detail-comment" data-content-detail-comment-item>
            <div class="avatar-button flash-detail-avatar">${initial}</div>
            <div class="flash-detail-comment-main"><strong>${name}</strong><span>${text}</span><span class="muted small">${meta}</span></div>
          </div>
        `).join("")}`;
      }
      view.querySelectorAll("[data-content-id]").forEach((node) => { node.dataset.contentId = item.id; });
      const hiddenRow = view.querySelector("[data-content-detail-record]");
      if (hiddenRow) {
        hiddenRow.dataset.contentDetailRecord = item.id;
        hiddenRow.dataset.contentId = item.id;
        [item.id, item.title, item.type, item.author, item.state, item.homeHot || "未设置", item.source, item.published, item.operator].forEach((value, index) => {
          if (hiddenRow.children[index]) hiddenRow.children[index].textContent = value;
        });
      }
      syncContentDetailActions(view);
      activateContentDetailTab("prompt");
    }

    const REAL_WORK_STATUS = {
      0: "草稿",
      1: "已发布",
      2: "已封禁",
      3: "已删除",
      4: "审核中",
      5: "已下架",
    };

    function normalizeRealWorkDetailItem(item = {}) {
      const legacyStatusCode = {
        草稿: 0,
        已发布: 1,
        审核通过: 1,
        已通过: 1,
        已封禁: 2,
        未通过: 2,
        已拒绝: 2,
        已删除: 3,
        待审核: 4,
        审核中: 4,
        复核中: 4,
        已下架: 5,
      };
      const statusCode = Number.isInteger(Number(item.statusCode))
        ? Number(item.statusCode)
        : legacyStatusCode[item.state] ?? 0;
      const typeText = {
        短剧漫剧: "漫剧",
        Prompt: "文本",
        视频生成: "视频",
        图片生成: "图片",
      }[item.type] || item.type || "—";
      const sourceText = /官方|平台/.test(item.source || "") ? "官方发布" : "用户投稿";
      const isHot = !/未设置|否/.test(item.homeHot || "未设置");
      const rawTags = Array.isArray(item.tags) ? item.tags : [];
      const tags = [...new Set([typeText, ...rawTags]
        .map((tag) => ({ 短剧漫剧: "漫剧", Prompt: "文本", 视频生成: "视频", 图片生成: "图片" }[tag] || tag))
        .filter((tag) => tag && !/待审核|审核通过|已通过|已拒绝|未通过|已发布|已下架|首页爆款|投稿/.test(tag)))].slice(0, 8);
      const metrics = item.metrics || {};
      return {
        id: item.id || "—",
        title: item.title || "未命名内容",
        type: typeText,
        author: item.author || "—",
        statusCode,
        status: REAL_WORK_STATUS[statusCode] || "—",
        source: sourceText,
        isHot,
        publishedAt: item.published || "—",
        updatedAt: item.updated || item.published || "—",
        tags: tags.length ? tags : [typeText],
        summary: item.summary && item.summary !== "—" ? item.summary : "暂无内容简介",
        prompt: item.prompt && item.prompt !== "—" ? item.prompt : "当前内容未提供提示词。",
        media: item.media || "",
        metrics: {
          like: String(metrics.like ?? 0),
          favorite: String(metrics.favorite ?? 0),
          comment: String(metrics.comment ?? 0),
        },
        comments: Array.isArray(item.apiComments) ? item.apiComments : [],
        activity: item.activity || "",
        activityId: item.activityId || "",
        activityRecordId: item.activityRecordId || "",
      };
    }

    function syncContentDetailActions(view) {
      if (!view) return;
      const contentId = view.dataset.runtimeContentId || "";
      const statusCode = Number(view.dataset.runtimeContentStatusCode || -1);
      const isHot = view.dataset.runtimeContentIsHot === "true";
      const lifecycle = view.querySelector('[data-content-op-action="lifecycle"]');
      const hotAction = view.querySelector('[data-content-op-action="home-hot"]');
      const auditAction = view.querySelector('[data-content-op-action="audit"]');
      const empty = view.querySelector("[data-content-detail-action-empty]");
      [lifecycle, hotAction, auditAction].forEach((button) => {
        if (button) button.hidden = true;
      });
      const setConfirmAction = (button, action, label, result, dangerous = false) => {
        if (!button) return;
        button.hidden = false;
        button.disabled = false;
        button.textContent = label;
        button.className = dangerous
          ? "btn danger ant-btn ant-btn-dangerous"
          : "btn primary ant-btn ant-btn-primary";
        button.dataset.dangerAction = action;
        button.dataset.dangerObjectId = contentId;
        button.dataset.dangerCurrentState = REAL_WORK_STATUS[statusCode] || "—";
        button.dataset.dangerResult = result;
        button.dataset.requiresConfirm = "true";
      };
      if (statusCode === 1) {
        setConfirmAction(lifecycle, "content-take-down", "下架内容", "作品状态更新为已下架，并重新请求作品详情。", true);
        setConfirmAction(
          hotAction,
          isHot ? "content-home-hot-remove" : "content-home-hot-set",
          isHot ? "取消首页爆款" : "设为首页爆款",
          isHot ? "取消作品首页爆款标记，并重新请求作品详情。" : "设置作品首页爆款标记，并重新请求作品详情。",
          isHot,
        );
      } else if ([2, 5].includes(statusCode)) {
        setConfirmAction(
          lifecycle,
          "content-restore",
          statusCode === 2 ? "解除封禁" : "恢复上架",
          statusCode === 2 ? "作品恢复为已发布，并重新请求作品详情。" : "作品恢复上架，并重新请求作品详情。",
        );
      } else if (statusCode === 4 && auditAction) {
        auditAction.hidden = false;
      }
      const hasAction = [lifecycle, hotAction, auditAction].some((button) => button && !button.hidden);
      if (empty) empty.hidden = hasAction;
    }

    function syncContentDetailPage() {
      const view = document.querySelector('.view[data-view="content-detail"]');
      if (!view) return;
      const currentId = String(new URLSearchParams(window.location.search).get("id") || "").trim();
      const catalogSamples = getCurrentCEndContentDetailSamples();
      const sourceItem = currentId ? (contentDetailSamples[currentId] || catalogSamples[currentId]) : null;
      const item = sourceItem ? normalizeRealWorkDetailItem(sourceItem) : null;
      const error = view.querySelector("[data-content-detail-error]");
      const errorMessage = view.querySelector("[data-content-detail-error-message]");
      const content = view.querySelector("[data-content-detail-content]");
      if (error) error.hidden = Boolean(item);
      if (errorMessage) {
        errorMessage.textContent = currentId
          ? `未找到内容 ${currentId}，请返回内容列表核对作品 ID。`
          : "缺少内容 ID，无法加载详情。";
      }
      if (content) content.hidden = !item;
      view.dataset.runtimeContentContext = item ? "known" : "unknown";
      if (!item) return;

      view.dataset.runtimeContentId = item.id;
      view.dataset.runtimeContentStatusCode = String(item.statusCode);
      view.dataset.runtimeContentState = item.status;
      view.dataset.runtimeContentIsHot = String(item.isHot);
      const setText = (selector, value) => {
        const node = view.querySelector(selector);
        if (node) node.textContent = value;
      };
      setText("[data-content-detail-title]", item.title);
      setText("[data-content-detail-summary]", item.summary);
      setText("[data-content-detail-prompt]", item.prompt);
      setText("[data-content-detail-id]", item.id);
      setText("[data-content-detail-author]", item.author);
      setText("[data-content-detail-source-text]", item.source);
      setText("[data-content-detail-published]", item.publishedAt);
      setText("[data-content-detail-updated]", item.updatedAt);
      setText("[data-content-detail-like]", item.metrics.like);
      setText("[data-content-detail-favorite]", item.metrics.favorite);
      setText("[data-content-detail-comment]", item.metrics.comment);
      const tags = view.querySelector("[data-content-detail-tags]");
      if (tags) tags.innerHTML = item.tags.map((tag) => `<span class="ant-tag">${escapeHtml(tag)}</span>`).join("");
      const state = view.querySelector("[data-content-detail-state]");
      if (state) state.innerHTML = `<span class="${tagClassForText(item.status)} ant-tag">${escapeHtml(item.status)}</span>`;
      const hot = view.querySelector("[data-content-detail-home-hot]");
      if (hot) hot.innerHTML = `<span class="${item.isHot ? "tag success" : "tag gray"} ant-tag">${item.isHot ? "已设置" : "未设置"}</span>`;
      const relation = view.querySelector("[data-content-detail-feature-relation]");
      if (relation) relation.textContent = item.isHot
        ? "当前内容已进入首页爆款展示。"
        : item.statusCode === 1
          ? "当前未设置；已发布内容可以建立首页爆款关系。"
          : "当前未设置；内容发布后才可管理首页爆款关系。";

      const image = view.querySelector("[data-content-detail-image]");
      const video = view.querySelector("[data-content-detail-video]");
      const mediaEmpty = view.querySelector("[data-content-detail-media-empty]");
      const isVideo = /\.(mp4|webm|mov)(\?|$)/i.test(item.media || "");
      if (image) {
        image.hidden = !item.media || isVideo;
        image.alt = item.title;
        if (item.media && !isVideo) image.src = item.media;
        else image.removeAttribute("src");
      }
      if (video) {
        video.hidden = !item.media || !isVideo;
        if (item.media && isVideo) video.src = item.media;
        else video.removeAttribute("src");
      }
      if (mediaEmpty) mediaEmpty.hidden = Boolean(item.media);

      const commentList = view.querySelector("[data-content-detail-comment-list]");
      const commentEmpty = view.querySelector("[data-content-detail-comments-empty]");
      if (commentList) {
        commentList.hidden = item.comments.length === 0;
        commentList.innerHTML = item.comments.map((comment) => `<div class="flash-detail-comment" data-content-detail-comment-item><div class="avatar-button flash-detail-avatar" data-antd-component="Avatar">${escapeHtml(String(comment.user_name || comment.user_no || "用").slice(0, 1))}</div><div class="flash-detail-comment-main"><strong>${escapeHtml(comment.user_name || comment.user_no || "社区用户")}</strong><span>${escapeHtml(comment.content || comment.content_text || "—")}</span></div></div>`).join("");
      }
      if (commentEmpty) commentEmpty.hidden = item.comments.length > 0;

      const activityPanel = view.querySelector("[data-content-detail-activity-panel]");
      if (activityPanel) activityPanel.hidden = !Boolean(item.activity || item.activityId || item.activityRecordId);
      setText("[data-content-detail-activity-name]", item.activity || "—");
      setText("[data-content-detail-activity-id]", item.activityId ? `活动 ID：${item.activityId}` : "");
      setText("[data-content-detail-activity-record-id]", item.activityRecordId ? `投稿记录：${item.activityRecordId}` : "");
      view.querySelectorAll("[data-content-id]").forEach((node) => { node.dataset.contentId = item.id; });
      const feedback = view.querySelector("[data-content-detail-action-feedback]");
      if (feedback) feedback.hidden = true;
      syncContentDetailActions(view);
      activateContentDetailTab("prompt");
    }

    function openContentDetailAudit() {
      const view = document.querySelector('.view[data-view="content-detail"]');
      if (!view || Number(view.dataset.runtimeContentStatusCode) !== 4) return;
      const modal = document.querySelector('[data-modal="content-detail-audit"]');
      if (!modal) return;
      const workId = modal.querySelector("[data-content-audit-work-id]");
      const workTitle = modal.querySelector("[data-content-audit-work-title]");
      if (workId) workId.textContent = view.dataset.runtimeContentId || "";
      if (workTitle) workTitle.textContent = view.querySelector("[data-content-detail-title]")?.textContent || "";
      const reason = modal.querySelector("[data-content-audit-reason]");
      if (reason) reason.value = "";
      const error = modal.querySelector("[data-content-audit-error]");
      if (error) error.hidden = true;
      setContentDetailAuditDecision("approve");
      modal.hidden = false;
      modal.classList.add("is-open");
      modal.querySelector(".modal")?.classList.add("is-open");
    }

    function setContentDetailAuditDecision(decision) {
      const modal = document.querySelector('[data-modal="content-detail-audit"]');
      if (!modal) return;
      modal.dataset.contentAuditDecision = decision;
      modal.querySelectorAll("[data-content-audit-decision]").forEach((button) => button.classList.toggle("is-active", button.dataset.contentAuditDecision === decision));
      const reasonField = modal.querySelector("[data-content-audit-reason-field]");
      if (reasonField) reasonField.hidden = decision !== "reject";
    }

    function submitContentDetailAudit() {
      const modal = document.querySelector('[data-modal="content-detail-audit"]');
      const view = document.querySelector('.view[data-view="content-detail"]');
      if (!modal || !view) return false;
      const decision = modal.dataset.contentAuditDecision || "approve";
      const reason = modal.querySelector("[data-content-audit-reason]")?.value.trim() || "";
      const error = modal.querySelector("[data-content-audit-error]");
      if (decision === "reject" && !reason) {
        if (error) {
          error.textContent = "拒绝时必须填写原因。";
          error.hidden = false;
        }
        return false;
      }
      if (error) error.hidden = true;
      modal.hidden = true;
      modal.classList.remove("is-open");
      modal.querySelector(".modal")?.classList.remove("is-open");
      const feedback = view.querySelector("[data-content-detail-action-feedback]");
      if (feedback) {
        feedback.textContent = decision === "approve" ? "审核通过请求已提交，详情已重新加载。" : "审核拒绝请求已提交，详情已重新加载。";
        feedback.hidden = false;
      }
      return true;
    }

