    function syncFlashDetailActions(view) {
      if (!view) return;
      const flashId = view.dataset.runtimeFlashId || "当前闪念";
      const state = view.dataset.runtimeFlashState || "";
      const lifecycle = view.querySelector('[data-content-op-action="flash-lifecycle"]');
      const reviewEntry = view.querySelector("[data-flash-review-entry]");
      const note = view.querySelector("[data-flash-detail-action-note]");
      const setDangerContract = (action, label, result, className) => {
        if (!lifecycle) return;
        lifecycle.hidden = false;
        lifecycle.disabled = false;
        lifecycle.className = className;
        lifecycle.textContent = label;
        lifecycle.dataset.dangerAction = action;
        lifecycle.dataset.dangerObjectId = flashId;
        lifecycle.dataset.dangerCurrentState = state;
        lifecycle.dataset.dangerResult = result;
      };
      if (lifecycle) lifecycle.hidden = true;
      if (reviewEntry) reviewEntry.hidden = true;
      if (state === "已下架") {
        setDangerContract("flash-restore", "恢复展示", "闪念改为已发布；C端恢复展示；正文、媒体、互动和操作记录保留", "btn primary");
        if (note) note.textContent = "闪念已下架，二次确认后即可恢复 C端展示。";
      } else if (state === "已发布") {
        setDangerContract("flash-take-down", "下架闪念", "闪念改为已下架；C端停止展示；正文、媒体、互动和操作记录保留", "btn danger");
        if (note) note.textContent = "闪念正在 C端展示；下架后保留正文、媒体、互动和处理记录。";
      } else if (/待审核|复核|退回|已拒绝/.test(state)) {
        if (reviewEntry) reviewEntry.hidden = false;
        if (note) note.textContent = "当前闪念尚未完成审核，请先进入审核工作台；通过并发布后才可管理 C端展示。";
      } else if (note) {
        note.textContent = "当前状态仅供核对，不提供恢复动作；如需处理请回到对应业务工作台。";
      }
    }

    function syncFlashDetailPage() {
      const view = document.querySelector('.view[data-view="flash-detail"]');
      if (!view) return;
      const currentId = String(new URLSearchParams(window.location.search).get("id") || "").trim();
      const knownItem = currentId ? flashDetailSamples[currentId] : null;
      const item = knownItem || {
        id: currentId || "—",
        author: "未找到对象",
        initial: "—",
        time: "请返回闪念管理列表",
        body: "当前闪念没有可展示的后台详情。",
        mediaState: "无",
        media: [],
        state: "未找到",
        published: "—",
        metrics: { like: "—", comment: "—", share: "—", favorite: "—" },
      };
      view.dataset.runtimeFlashContext = knownItem ? "known" : "unknown";
      view.dataset.runtimeFlashId = item.id;
      view.dataset.runtimeFlashState = item.state;
      const error = view.querySelector("[data-flash-detail-error]");
      const content = view.querySelector("[data-flash-detail-content]");
      if (error) {
        error.hidden = Boolean(knownItem);
        const message = error.querySelector("[data-flash-detail-error-message]");
        if (message) message.textContent = currentId
          ? `未找到闪念 ${currentId}，或详情响应与当前对象不一致。`
          : "缺少闪念 ID，无法加载详情。";
      }
      if (content) content.hidden = !knownItem;
      const setText = (selector, value) => {
        const node = view.querySelector(selector);
        if (node) node.textContent = value;
      };
      const card = view.querySelector("[data-flash-detail-card]");
      if (card) card.dataset.flashId = item.id;
      setText(".flash-detail-author-line .flash-detail-avatar", item.initial);
      setText("[data-flash-detail-author]", item.author);
      setText("[data-flash-detail-time]", item.time);
      setText("[data-flash-detail-body]", item.body);
      setText("[data-flash-detail-id]", item.id);
      setText("[data-flash-detail-meta-author]", item.author);
      setText("[data-flash-detail-media-state]", item.mediaState);
      setText("[data-flash-detail-published]", item.published);
      setText("[data-flash-detail-like]", item.metrics.like);
      setText("[data-flash-detail-comment-count]", item.metrics.comment);
      setText("[data-flash-detail-share]", item.metrics.share);
      setText("[data-flash-detail-favorite]", item.metrics.favorite);
      const state = view.querySelector("[data-flash-detail-state]");
      if (state) state.innerHTML = `<span class="${tagClassForText(item.state)}">${item.state}</span>`;
      const mediaGrid = view.querySelector("[data-flash-detail-media-grid]");
      if (mediaGrid) {
        mediaGrid.dataset.mediaCount = String(item.media.length);
        mediaGrid.innerHTML = item.media.map((label) => `<div class="flash-detail-media-item" data-flash-detail-media-item>${label}</div>`).join("");
      }
      const feedback = view.querySelector("[data-flash-detail-action-feedback]");
      if (feedback) feedback.hidden = true;
      syncFlashDetailActions(view);
    }

    function syncTemplateListRow(row) {
      if (!row) return;
      const enabled = row.dataset.templateEnabled === "true";
      const hot = row.dataset.templateHot === "true";
      const workId = row.dataset.contentId || row.dataset.templateId || row.cells[0]?.textContent?.trim() || "";
      const status = enabled && hot ? "展示中" : "停用";
      row.dataset.status = status;
      const statusCell = row.querySelector("[data-template-list-status-cell]") || row.children[7];
      if (statusCell) statusCell.innerHTML = `<span class="${status === "展示中" ? "tag success" : "tag gray"}">${status}</span>`;
      const relationAction = hot
        ? `<button class="ant-btn ant-btn-link ant-btn-dangerous" type="button" data-template-list-action="cancel-hot" data-danger-action="template-cancel-hot" data-danger-object-id="${escapeAttribute(workId)}" data-danger-current-state="${status}" data-danger-result="取消热门模板关系" data-requires-confirm="true" data-antd-component="Button">取消热门模板</button>`
        : `<button class="ant-btn ant-btn-link" type="button" data-template-list-action="set-hot" data-danger-action="template-set-hot" data-danger-object-id="${escapeAttribute(workId)}" data-danger-current-state="${status}" data-danger-result="恢复热门模板关系" data-requires-confirm="true" data-antd-component="Button">设置热门模板</button>`;
      const enabledAction = enabled
        ? `<button class="ant-btn ant-btn-link ant-btn-dangerous" type="button" data-template-list-action="disable" data-danger-action="template-disable" data-danger-object-id="${escapeAttribute(workId)}" data-danger-current-state="${status}" data-danger-result="下架官方作品并停止 C 端展示" data-requires-confirm="true" data-antd-component="Button">停用</button>`
        : `<button class="ant-btn ant-btn-link" type="button" data-template-list-action="enable" data-danger-action="template-enable" data-danger-object-id="${escapeAttribute(workId)}" data-danger-current-state="${status}" data-danger-result="发布官方作品并恢复热门模板关系" data-requires-confirm="true" data-antd-component="Button">启用</button>`;
      const actionCell = row.children[9];
      if (actionCell) actionCell.innerHTML = `<div class="op-list template-config-table-actions"><button class="ant-btn ant-btn-link" type="button" data-open-content-modal="template-edit" data-antd-component="Button">编辑</button><span class="template-config-table-action-dot">·</span>${relationAction}<span class="template-config-table-action-dot">·</span>${enabledAction}</div>`;
    }

