      view.addEventListener("input", markDirty);
      view.addEventListener("change", markDirty);
      const scoreCompositionInputs = [...view.querySelectorAll("[data-competition-weight],[data-competition-heat-coefficient]")];
      scoreCompositionInputs.forEach((input) => input.addEventListener("input", refreshScoringFormula));
