          const mode = activeCompetitionTrackRow ? "edit" : "create";
          modal.querySelector('[data-competition-track-field="mode"]').value = mode;
          modal.querySelector('[data-competition-track-field="id"]').value = activeCompetitionTrackRow?.dataset.trackId || `TRACK-${String(view.querySelectorAll("[data-competition-track-row]").length + 1).padStart(2, "0")}`;
          modal.querySelector('[data-competition-track-field="name"]').value = activeCompetitionTrackRow?.dataset.trackName || "";
          modal.querySelector('[data-competition-track-field="topic"]').value = activeCompetitionTrackRow?.dataset.trackTopic || "";
          modal.querySelector('[data-competition-track-field="description"]').value = activeCompetitionTrackRow?.dataset.trackDescription || "";
          modal.querySelector('[data-competition-track-field="free"]').value = activeCompetitionTrackRow?.dataset.trackFree || "否";
          modal.querySelector('[data-competition-track-field="order"]').value = activeCompetitionTrackRow?.dataset.trackOrder || view.querySelectorAll("[data-competition-track-row]").length + 1;
