          const pending = Math.max(0, Number(totalCount) - Number(done));
          const percent = Number(totalCount) ? Math.round(Number(done) / Number(totalCount) * 100) : 0;
          const tracks = String(row.dataset.judgeScope || "待分配").split("、");
          const totalWorks = Number(totalCount || 0);
