    let tutorialActiveStatus = "published";

    function readTutorialAdminCatalog() {
      const injected = document.querySelector("script[data-tutorial-admin-catalog]")?.textContent || "";
      if (injected) {
        try {
          const records = JSON.parse(injected);
          if (Array.isArray(records)) return records;
        } catch {}
      }
      return [...document.querySelectorAll('tr[data-tutorial-id]')].map((row) => ({
        tutorialNo: row.dataset.tutorialId || "",
        title: row.dataset.tutorialTitle || "",
        sectionName: row.dataset.tutorialCategory || "",
        status: row.dataset.tutorialStatus || "",
        cover: row.querySelector("[data-tutorial-cover]")?.dataset.tutorialCover || "",
        viewCount: Number(row.dataset.viewCount || 0),
        commentCount: Number(row.dataset.commentCount || 0),
        createdAt: row.dataset.createdAt || "",
      })).filter((item) => item.tutorialNo);
    }

    function initTutorialPreviewPage() {
      const view = document.querySelector('.view[data-view="tutorial-preview"]');
      if (!view) return;
      const params = new URLSearchParams(window.location.search);
      const tutorialNo = String(params.get("tutorial_no") || params.get("tutorial_id") || params.get("post_id") || "").trim();
      const empty = view.querySelector("[data-tutorial-preview-empty]");
      const emptyText = view.querySelector("[data-tutorial-preview-empty-text]");
      const detail = view.querySelector("[data-tutorial-preview-detail]");
      const record = readTutorialAdminCatalog().find((item) => String(item.tutorialNo) === tutorialNo);
      if (!tutorialNo || !record) {
        if (emptyText) emptyText.textContent = tutorialNo
          ? `未找到教程 ${tutorialNo}，无法加载教程预览。`
          : "缺少教程编号，无法加载教程预览。";
        if (empty) empty.hidden = false;
        if (detail) detail.hidden = true;
        return;
      }
      if (empty) empty.hidden = true;
      if (detail) detail.hidden = false;
      const setText = (selector, value) => {
        const node = view.querySelector(selector);
        if (node) node.textContent = value;
      };
      setText("[data-tutorial-preview-title]", record.title || "教程预览");
      setText("[data-tutorial-preview-id]", record.tutorialNo);
      setText("[data-tutorial-preview-section]", record.sectionName || "暂无归属板块");
      setText("[data-tutorial-preview-views]", String(record.viewCount ?? 0));
      setText("[data-tutorial-preview-comments]", String(record.commentCount ?? 0));
      setText("[data-tutorial-preview-likes]", String(record.likeCount ?? 0));
      setText("[data-tutorial-preview-status]", record.status === "published" ? "已发布" : "未发布");
      setText("[data-tutorial-preview-source]", record.source === "personal" ? "个人" : "官方");
      setText("[data-tutorial-preview-published]", record.publishedAt || "—");
      setText("[data-tutorial-preview-created]", record.createdAt || "—");
      setText("[data-tutorial-preview-updated]", record.updatedAt || "—");
      const status = view.querySelector("[data-tutorial-preview-status]");
      if (status) status.className = record.status === "published" ? "ant-tag ant-tag-success" : "ant-tag";
      const cover = view.querySelector("[data-tutorial-preview-cover]");
      const coverWrap = view.querySelector(".tutorial-preview-cover");
      const coverEmpty = view.querySelector("[data-tutorial-preview-cover-empty]");
      if (cover && record.cover) {
        cover.src = record.cover;
        cover.alt = `${record.title || record.tutorialNo}封面`;
        if (coverWrap) coverWrap.hidden = false;
        if (coverEmpty) coverEmpty.hidden = true;
      } else {
        if (coverWrap) coverWrap.hidden = true;
        if (coverEmpty) coverEmpty.hidden = false;
      }
    }

    function renderTutorialRowActions(row) {
      if (!row) return;
      const actionCell = row.lastElementChild;
      const tutorialId = row.dataset.tutorialId || "";
      const title = row.dataset.tutorialTitle || "";
      const published = row.dataset.tutorialStatus === "published";
      const currentState = published ? "已发布" : "草稿";
      const deleteResult = published ? "教程进入已删除状态；C端停止展示；历史数据保留" : "教程进入已删除状态；草稿内容不可恢复；操作记录保留";
      actionCell.innerHTML = `<div class="op-list">${published ? '<button class="ant-btn ant-btn-link" data-antd-component="Button" data-antd-button-type="link" data-tutorial-action="view">查看</button>' : ""}<button class="ant-btn ant-btn-link" data-antd-component="Button" data-antd-button-type="link" data-open-content-modal="tutorial-edit">编辑</button><button class="ant-btn ant-btn-link" data-antd-component="Button" data-antd-button-type="link" data-tutorial-action="${published ? "unpublish" : "publish"}">${published ? "下架" : "发布"}</button><button class="ant-btn ant-btn-link ant-btn-dangerous" data-antd-component="Button" data-antd-button-type="link" data-danger-action="tutorial-delete" data-danger-object-id="${escapeAttribute(`${tutorialId} · ${title}`)}" data-danger-current-state="${currentState}" data-danger-result="${deleteResult}" data-requires-confirm="true">删除</button></div>`;
    }

    function setTutorialSectionValue(value = "all") {
      const select = document.querySelector('.view[data-view="tutorial-management"] [data-tutorial-filter="section"]');
      if (!select) return;
      const normalized = String(value || "all");
      select.dataset.value = normalized;
      const selectedOption = [...select.querySelectorAll("[data-tutorial-section-option]")]
        .find((option) => option.dataset.tutorialSectionOption === normalized);
      const label = select.querySelector("[data-tutorial-section-label]");
      if (label) {
        label.textContent = selectedOption?.textContent?.trim() || "板块筛选";
        label.className = normalized === "all" ? "ant-select-selection-placeholder" : "ant-select-selection-item";
      }
      select.querySelectorAll("[data-tutorial-section-option]").forEach((option) => {
        const active = option === selectedOption;
        option.classList.toggle("ant-select-item-option-selected", active);
        option.setAttribute("aria-selected", String(active));
      });
    }

    function toggleTutorialSectionSelect(forceOpen) {
      const select = document.querySelector('.view[data-view="tutorial-management"] [data-tutorial-filter="section"]');
      if (!select) return;
      const popup = select.querySelector("[data-tutorial-section-popup]");
      const trigger = select.querySelector("[data-tutorial-section-trigger]");
      const open = typeof forceOpen === "boolean" ? forceOpen : !select.classList.contains("ant-select-open");
      select.classList.toggle("ant-select-open", open);
      if (popup) popup.hidden = !open;
      if (trigger) trigger.setAttribute("aria-expanded", String(open));
    }

    function syncTutorialKeywordClear() {
      const view = document.querySelector('.view[data-view="tutorial-management"]');
      const input = view?.querySelector('[data-tutorial-filter="keyword"]');
      const clear = view?.querySelector("[data-tutorial-keyword-clear]");
      if (clear) clear.hidden = !String(input?.value || "");
    }

    function applyTutorialFilters() {
      const view = document.querySelector('.view[data-view="tutorial-management"]');
      if (!view) return;
      const keywordInput = view.querySelector('[data-tutorial-filter="keyword"]');
      const sectionSelect = view.querySelector('[data-tutorial-filter="section"]');
      const sectionField = view.querySelector("[data-tutorial-section-filter]");
      const categoryHeader = view.querySelector('[data-tutorial-field="category"]');
      const emptyCell = view.querySelector("[data-tutorial-empty] td");
      const keyword = String(keywordInput?.value || "").trim().toLowerCase();
      const draftActive = tutorialActiveStatus === "draft";
      if (sectionField) sectionField.hidden = draftActive;
      if (categoryHeader) categoryHeader.hidden = draftActive;
      if (emptyCell) emptyCell.colSpan = draftActive ? 6 : 7;
      if (tutorialActiveStatus === "draft" && sectionSelect) setTutorialSectionValue("all");
      const section = sectionSelect?.dataset.value || "all";
      let visibleCount = 0;
      view.querySelectorAll('[data-table="official-tutorial-management"] tbody tr[data-tutorial-id]').forEach((row) => {
        if (row.children[2]) row.children[2].hidden = draftActive;
        const matchesStatus = row.dataset.tutorialStatus === tutorialActiveStatus;
        const matchesKeyword = !keyword || String(row.dataset.tutorialTitle || "").toLowerCase().includes(keyword);
        const matchesSection = section === "all" || row.dataset.tutorialCategory === section;
        row.hidden = !(matchesStatus && matchesKeyword && matchesSection);
        if (!row.hidden) visibleCount += 1;
      });
      const empty = view.querySelector("[data-tutorial-empty]");
      if (empty) empty.hidden = visibleCount !== 0;
      syncTutorialKeywordClear();
    }

    function setTutorialStatus(row, nextStatus) {
      if (!row) return;
      row.dataset.tutorialStatus = nextStatus;
      row.dataset.tutorialCatalogItem = nextStatus === "published" ? "true" : "false";
      renderTutorialRowActions(row);
      const result = document.querySelector("[data-tutorial-save-result]");
      if (result) {
        result.textContent = nextStatus === "published"
          ? `教程 ${row.dataset.tutorialId} 已发布；C端公开列表可读取该对象。`
          : `教程 ${row.dataset.tutorialId} 已下架并回到草稿箱；C端停止展示。`;
        result.hidden = false;
      }
      applyTutorialFilters();
    }

    document.addEventListener("keydown", (event) => {
      const roleSelect = event.target.closest("[data-admin-role-select]");
      if (event.key === "Escape") {
        closeAnalyticsMetricHelp();
        closeAnalyticsDatePicker();
        closeAdminRoleSelects();
        toggleTutorialSectionSelect(false);
        return;
      }
      const tutorialSectionOption = event.target.closest("[data-tutorial-section-option]");
      if (tutorialSectionOption && ["Enter", " "].includes(event.key)) {
        event.preventDefault();
        setTutorialSectionValue(tutorialSectionOption.dataset.tutorialSectionOption);
        toggleTutorialSectionSelect(false);
        applyTutorialFilters();
        return;
      }
      const tutorialSectionTrigger = event.target.closest("[data-tutorial-section-trigger]");
      if (tutorialSectionTrigger && ["Enter", " ", "ArrowDown"].includes(event.key)) {
        event.preventDefault();
        toggleTutorialSectionSelect(true);
        return;
      }
      if (!roleSelect) return;
      const option = event.target.closest("[data-admin-role-option]");
      if (option && ["Enter", " "].includes(event.key)) {
        event.preventDefault();
        toggleAdminRoleOption(option);
        return;
      }
      const trigger = event.target.closest("[data-admin-role-select-trigger]");
      if (trigger && ["Enter", " ", "ArrowDown"].includes(event.key)) {
        event.preventDefault();
        toggleAdminRoleSelect(roleSelect, true);
      }
    });

