        if(kind==='content'){const states=[['all','全部状态'],['draft','草稿'],['pending','审核中'],['approved','审核通过待发布'],['rejected','审核拒绝'],['failed','审核技术失败'],['published','已发布'],['offline','已下架']];grid.querySelector('[data-analytics-filter-control="state"]').innerHTML=states.map(([v,l])=>`<option value="${v}">${l}</option>`).join('');grid.querySelector('[data-analytics-filter-control="author"]').value='user';guide?.rules.unshift('内容存量包含截止时各状态，已发布只是子集；内容存量与结构支持按当前状态、话题、作品/帖子拆分，状态按每个查询截止重算。发生量不套用当前状态过滤。');}
        if(kind==='quality'){grid.insertAdjacentHTML('beforeend',control('type','内容对象',[['all','作品与帖子'],['work','仅作品'],['post','仅帖子']]));guide?.rules.unshift('审核积压、耗时、通过率和技术失败率支持作品/帖子筛选与分组；非审核指标清除该条件，审核轮次与内容对象不混算。');}
        if(kind==='activity'){const period=grid.querySelector('[data-analytics-filter-control="period"]');period.innerHTML='<option value="all">全部期次</option><option value="current">演示第 2 期（DEMO-P02）</option><option value="history">演示第 1 期（DEMO-P01）</option>';grid.insertAdjacentHTML('beforeend',control('task-day','签到期次',[['all','选择签到日期'],...[...new Set(domainFacts.map(row=>row.day))].sort().reverse().map(day=>[day,day])]));guide?.rules.unshift('任务完成率仅选择具体任务和期次后按 user_no 去重计算；签到使用具体自然日期。全部任务或全部期次显示 — 并提示选择，完成用户和完成次数仍可汇总，不以用户×任务×期次替代人数。current/history 仅为两个独立演示期次键，分别显示 DEMO-P02/DEMO-P01，不表示当前或历史期次集合。');}
        if(kind==='content')grid.insertAdjacentHTML('beforeend',control('content','内容',[['all','全部内容']]));
        // 未联动的旧演示表保留在源中供历史追溯，不再暴露为当前查询结果。
        view.dataset.domainReady='true';
