      if (event.target.closest("[data-official-account-submit]") && saveOfficialAccount()) closeLayers();

      if (event.target.closest("[data-official-content-submit]") && saveOfficialContent()) closeLayers();

      if (event.target.closest("[data-announcement-submit]") && saveAnnouncement()) closeLayers();

      const announcementPublish = event.target.closest("[data-announcement-publish]");
