      const userGovernanceSubmit = event.target.closest("[data-user-governance-submit]");
      if (userGovernanceSubmit && userGovernanceController.save()) closeLayers();

      const userPointsAdjustmentSubmit = event.target.closest("[data-user-points-adjustment-submit]");
      if (userPointsAdjustmentSubmit && saveUserPointsAdjustment()) closeLayers();

      const contentCategorySubmit = event.target.closest("[data-content-category-submit]");
