    function initAnalyticsAtomicCatalog() {
      const view=document.querySelector('.view[data-view="analytics-metrics"]');if(!view)return;
      const names={'G-06':'触点渠道分布','G-08':'注册触点渠道','Q-03':'未记录渠道占比'};
      view.querySelectorAll('[data-analytics-metric-row]').forEach(row=>{
        const items=analyticsAtomicCatalog.filter(item=>item[0]===row.dataset.id);
        row.dataset.atomicSearch=items.map(item=>item[1]).join(' ');
        if(names[row.dataset.id]){row.dataset.name=names[row.dataset.id];row.cells[1].firstChild.textContent=names[row.dataset.id];}
        const trigger=row.querySelector('[data-analytics-metric-open]');
        if(trigger&&items.length){trigger.dataset.name=row.dataset.name;trigger.dataset.definition=items.map(item=>item[1]).join('、');}
      });
      view.querySelector('[data-analytics-metric-filter="keyword"]').placeholder='搜索具体指标或编号，如会话数、审核通过率';
      const source=view.querySelector('[data-analytics-metric-filter="source"]');if(source){source.value='';source.closest('.field').hidden=true;}
    }
    function renderAnalyticsAtomicDefinition(detail,id) {
      let box=detail.querySelector('[data-atomic-definitions]');
      if(!box){box=document.createElement('div');box.dataset.atomicDefinitions='true';box.className='table-wrap';detail.append(box);}
      const items=analyticsAtomicCatalog.filter(item=>item[0]===id);
      let common=detail.querySelector('[data-atomic-common]');
      if(!common){common=document.createElement('p');common.dataset.atomicCommon='true';common.className='muted small';common.textContent='比率以百分比展示（商 × 100%）；业务人数按 user_no 去重，时间采用北京时间。';box.before(common);}
      box.innerHTML='<table data-component-library="ant-design-vue" data-antd-component="Table"><thead><tr><th>具体指标</th><th>计算方式</th><th>去重对象</th><th>统计时间</th><th>限制</th></tr></thead><tbody>'+items.map(item=>'<tr>'+item.slice(1).map(value=>'<td class="wrap">'+escapeHtml(value)+'</td>').join('')+'</tr>').join('')+'</tbody></table>';
      ['definition','formula','source','exclusion','boundary'].forEach(key=>{const node=detail.querySelector('[data-analytics-metric-detail-'+key+']');if(node)node.hidden=true;});
    }
    function initAnalyticsScopeReduction() {
      ['analytics-overview','analytics-growth','analytics-users','analytics-quality','analytics-metrics'].forEach(key=>{
        const guide=walkthroughPageCatalog[key];if(!guide)return;
        guide.rules=guide.rules.filter(rule=>!['直接访问','站内来源','外部来源','四类','来源类型','系统分类'].some(word=>rule.includes(word)));
        guide.rules.unshift('渠道仅使用后台注册来源及 UTM 渠道值；空值显示未记录渠道，非空历史编码保留在历史 / 未匹配渠道，不根据 referrer 推断分类。');
        if(['analytics-growth','analytics-users'].includes(key))guide.rules.unshift('观察窗已满人数仅作激活、首次行为等指标的分母说明，不进入主指标选择；旧 mature 链接转到激活率。');
        if(key==='analytics-metrics')guide.rules.unshift('按具体展示指标名称搜索；定义中逐行展示计算方式、去重对象、统计时间与限制，逐项对应需求第 5.2 节。');
      });
      const url = new URL(location.href);
      const retired = ['direct','onsite','external','external_other'];
      let cleared = false;
      if(url.searchParams.has('f_source-type')) { cleared = url.searchParams.get('f_source-type') !== 'all'; url.searchParams.delete('f_source-type'); }
      ['f_channel','f_source'].forEach(key => { if(retired.includes(url.searchParams.get(key))) { url.searchParams.set(key,'all'); cleared=true; } });
      if(url.searchParams.get('growth_group')==='source-type')url.searchParams.set('growth_group','channel');
      if(url.searchParams.get('growth_metric')==='mature')url.searchParams.set('growth_metric','activation');
      if(url.searchParams.get('journey_metric')==='mature')url.searchParams.set('journey_metric','activation');
      history.replaceState({},'',url);
      document.querySelectorAll('.view[data-view^="analytics-"] [data-analytics-filter-control="source-type"]').forEach(control=>{control.innerHTML='<option value="all">全部</option>';control.disabled=true;control.closest('.field').hidden=true;});
      document.querySelectorAll('.view[data-view^="analytics-"] option').forEach(option=>{if(option.value==='missing')option.textContent='未记录渠道';});
      if(cleared){const view=document.querySelector('.view.is-active');const note=document.createElement('p');note.className='muted small';note.textContent='旧链接中的来源分类已取消，本次未应用该条件。';view?.prepend(note);}
    }
